// Beastkeeping, grown (beasts.ts, beastfolk.ts): the new companions, their knacks and produce, training, grooming, the drake egg, the Keeper's Trial and Pip's menagerie. One row per English text, its translations in TABLE_LANGUAGES' order (see table.ts).
import type { Row } from "./table.ts";

export const BEASTS_GROWN: Readonly<Record<string, Row>> = {
  "Hen": ["雌鶏", "암탉", "母鸡", "母雞", "Gà mái", "Ayam betina", "แม่ไก่", "Tavuk", "Gallina", "Galinha", "Курица", "Курка"],
  "Your salamander's bite burns!": ["サラマンダーの噛みつきが焼け付く！", "도롱뇽의 물기가 불타오른다!", "你的火蜥蜴一口咬下，灼烧起来！", "你的火蜥蜴一口咬下，灼燒起來！", "Vết cắn của kỳ giông bỏng rát!", "Gigitan salamandermu membakar!", "รอยกัดของซาลาแมนเดอร์ของเจ้าแผดเผา!", "Semenderinin ısırığı yakıyor!", "¡El mordisco de tu salamandra quema!", "A mordida da sua salamandra queima!", "Укус вашей саламандры обжигает!", "Укус вашої саламандри обпікає!"],
  "Your hound worries at it!": ["猟犬が食らいついて振り回す！", "사냥개가 물고 늘어진다!", "你的猎犬死咬不放！", "你的獵犬死咬不放！", "Chó săn của ngươi cắn xé nó!", "Anjingmu menggigit dan mengoyaknya!", "สุนัขล่าเนื้อของเจ้างับไม่ปล่อย!", "Tazın onu dişleyip sarsıyor!", "¡Tu sabueso lo zarandea a dentelladas!", "Seu cão o sacode nos dentes!", "Ваш пёс треплет его!", "Ваш пес шарпає його!"],
  "Your boar gores it!": ["猪が牙で突き上げる！", "멧돼지가 엄니로 들이받는다!", "你的野猪用獠牙挑起它！", "你的野豬用獠牙挑起牠！", "Lợn rừng của ngươi húc nanh vào nó!", "Babi hutanmu menanduknya dengan taring!", "หมูป่าของเจ้าขวิดมัน!", "Yaban domuzun onu dişleriyle deşiyor!", "¡Tu jabalí lo cornea con los colmillos!", "Seu javali o fere com as presas!", "Ваш кабан распарывает его клыками!", "Ваш кабан розпорює його іклами!"],
  "Your wolf savages it!": ["狼が猛然と襲いかかる！", "늑대가 사납게 물어뜯는다!", "你的狼凶猛撕咬！", "你的狼凶猛撕咬！", "Sói của ngươi xé xác nó!", "Serigalamu mencabik-cabiknya!", "หมาป่าของเจ้าขย้ำมันอย่างดุร้าย!", "Kurdun onu parçalıyor!", "¡Tu lobo lo despedaza!", "Seu lobo o dilacera!", "Ваш волк рвёт его!", "Ваш вовк шматує його!"],
  "Your bear mauls it!": ["熊が叩きのめす！", "곰이 마구 할퀴어 댄다!", "你的熊一通猛拍！", "你的熊一通猛拍！", "Gấu của ngươi vồ nát nó!", "Beruangmu mencakarnya habis-habisan!", "หมีของเจ้าตะปบมันเละ!", "Ayın onu hırpalıyor!", "¡Tu oso lo destroza a zarpazos!", "Seu urso o estraçalha!", "Ваш медведь мнёт его!", "Ваш ведмідь мне його!"],
  "Scatter grain for a farm hen, visit after visit, until she follows you.": ["農場の雌鶏に穀物をまいてやろう。何度も通えば、ついて来るようになる。", "농장 암탉에게 곡식을 뿌려 줘라. 찾아갈 때마다 주다 보면 너를 따라온다.", "给农场的母鸡撒谷子，一次又一次，直到她跟着你走。", "給農場的母雞撒穀子，一次又一次，直到她跟著你走。", "Rải thóc cho một con gà mái ở trang trại, hết lần này đến lần khác, cho đến khi nó theo ngươi.", "Taburkan biji-bijian untuk ayam betina di peternakan, berkali-kali, sampai ia mengikutimu.", "โปรยเมล็ดพืชให้แม่ไก่ในฟาร์ม ครั้งแล้วครั้งเล่า จนกว่ามันจะตามเจ้าไป", "Bir çiftlik tavuğuna tekrar tekrar tane serp, ta ki seni izleyene dek.", "Echa grano a una gallina de granja, visita tras visita, hasta que te siga.", "Jogue grãos para uma galinha da fazenda, visita após visita, até ela seguir você.", "Сыпьте зерно курице на ферме, раз за разом, пока она не пойдёт за вами.", "Сипте зерно курці на фермі, раз за разом, доки вона не піде за вами."],
  "A brown hen with opinions. She lays where she likes, which is wherever you are.": ["一家言ある茶色い雌鶏。好きな所で卵を産む。つまり、あなたのいる所で。", "고집 있는 갈색 암탉. 원하는 곳에 알을 낳는데, 그게 바로 네가 있는 곳이다.", "一只很有主见的棕色母鸡。她想在哪儿下蛋就在哪儿下，也就是你在的地方。", "一隻很有主見的棕色母雞。她想在哪兒下蛋就在哪兒下，也就是你在的地方。", "Một con gà mái nâu có chính kiến. Nó đẻ ở đâu nó thích, tức là chỗ ngươi đang đứng.", "Ayam betina cokelat yang punya pendirian. Ia bertelur di mana ia suka, yaitu di mana pun kau berada.", "แม่ไก่สีน้ำตาลที่มีความคิดเป็นของตัวเอง มันวางไข่ตรงไหนก็ได้ที่ชอบ ซึ่งก็คือที่ที่เจ้าอยู่", "Kafasının dikine giden kahverengi bir tavuk. İstediği yere yumurtlar, yani neredeysen oraya.", "Una gallina parda con opiniones. Pone donde le place, que es dondequiera que estés.", "Uma galinha marrom cheia de opinião. Bota onde quer, ou seja, onde você estiver.", "Бурая курица с характером. Несётся, где ей вздумается, то есть там, где вы.", "Бура курка з характером. Несеться, де їй заманеться, тобто там, де ви."],
  "Put a halter on a sheep (the beastkeepers sell them).": ["羊に端綱をかけよう（獣使いが売っている）。", "양에게 고삐를 씌워라 (조련사들이 판다).", "给一只羊套上笼头（驯兽人有卖）。", "給一隻羊套上籠頭（馴獸人有賣）。", "Tròng dây dắt cho một con cừu (người nuôi thú có bán).", "Pasang tali kekang pada seekor domba (para penjinak menjualnya).", "สวมบังเหียนให้แกะ (ผู้เลี้ยงสัตว์มีขาย)", "Bir koyuna yular tak (bakıcılar satar).", "Ponle un ronzal a una oveja (los cuidadores de bestias los venden).", "Coloque um cabresto numa ovelha (os tratadores vendem).", "Наденьте недоуздок на овцу (их продают звероводы).", "Надіньте недоуздок на вівцю (їх продають звірівники)."],
  "A woolly sheep on a halter. Every so often it's woolly enough to shear, and you do.": ["端綱をつけた毛むくじゃらの羊。ときどき刈れるほど毛が伸びるので、刈ってやる。", "고삐를 맨 털북숭이 양. 이따금 깎을 만큼 털이 자라면, 너는 깎는다.", "一只套着笼头的毛茸茸的羊。时不时毛就长到能剪了，你便剪下来。", "一隻套著籠頭的毛茸茸的羊。時不時毛就長到能剪了，你便剪下來。", "Một con cừu lông xù đeo dây dắt. Thỉnh thoảng lông đủ dày để xén, và ngươi xén.", "Domba berbulu lebat bertali kekang. Sesekali bulunya cukup tebal untuk dicukur, dan kau mencukurnya.", "แกะขนฟูที่สวมบังเหียน บางครั้งขนก็ยาวพอจะตัด แล้วเจ้าก็ตัด", "Yularlı, yünlü bir koyun. Arada bir kırkılacak kadar yünlenir, sen de kırkarsın.", "Una oveja lanuda con ronzal. De vez en cuando tiene lana de sobra para esquilar, y la esquilas.", "Uma ovelha lanuda de cabresto. De vez em quando tem lã para tosquiar, e você tosquia.", "Шерстистая овца на недоуздке. Время от времени шерсти хватает на стрижку, и вы стрижёте.", "Вовниста вівця на недоуздку. Час від часу вовни досить на стрижку, і ви стрижете."],
  "Milk cow": ["乳牛", "젖소", "奶牛", "乳牛", "Bò sữa", "Sapi perah", "วัวนม", "Süt ineği", "Vaca lechera", "Vaca leiteira", "Дойная корова", "Дійна корова"],
  "Put a halter on a cow (the beastkeepers sell them).": ["牛に端綱をかけよう（獣使いが売っている）。", "소에게 고삐를 씌워라 (조련사들이 판다).", "给一头牛套上笼头（驯兽人有卖）。", "給一頭牛套上籠頭（馴獸人有賣）。", "Tròng dây dắt cho một con bò (người nuôi thú có bán).", "Pasang tali kekang pada seekor sapi (para penjinak menjualnya).", "สวมบังเหียนให้วัว (ผู้เลี้ยงสัตว์มีขาย)", "Bir ineğe yular tak (bakıcılar satar).", "Ponle un ronzal a una vaca (los cuidadores de bestias los venden).", "Coloque um cabresto numa vaca (os tratadores vendem).", "Наденьте недоуздок на корову (их продают звероводы).", "Надіньте недоуздок на корову (їх продають звірівники)."],
  "A patient milk cow on a halter. Carry a bucket, and now and then it's full.": ["端綱をつけた辛抱強い乳牛。バケツを持っていれば、ときどきいっぱいになる。", "고삐를 맨 참을성 많은 젖소. 양동이를 들고 다니면 이따금 가득 찬다.", "一头套着笼头、性子温顺的奶牛。带上桶，时不时就满了。", "一頭套著籠頭、性子溫順的乳牛。帶上桶，時不時就滿了。", "Một con bò sữa kiên nhẫn đeo dây dắt. Mang theo xô, thỉnh thoảng nó sẽ đầy.", "Sapi perah yang sabar bertali kekang. Bawa ember, dan sesekali ember itu penuh.", "วัวนมใจเย็นที่สวมบังเหียน พกถังไว้ แล้วบางครั้งมันก็เต็ม", "Yularlı, sabırlı bir süt ineği. Yanında kova taşı, arada bir dolar.", "Una vaca lechera paciente con ronzal. Lleva un cubo y, de vez en cuando, se llena.", "Uma vaca leiteira paciente de cabresto. Leve um balde e, de vez em quando, ele enche.", "Терпеливая дойная корова на недоуздке. Носите с собой ведро, и время от времени оно полное.", "Терпляча дійна корова на недоуздку. Носіть із собою відро, і час від часу воно повне."],
  "Silk spider": ["絹蜘蛛", "비단거미", "丝蛛", "絲蛛", "Nhện tơ", "Laba-laba sutra", "แมงมุมไหม", "İpek örümceği", "Araña de seda", "Aranha-da-seda", "Шелковый паук", "Шовковий павук"],
  "Feed a forest spider raw chicken, visit after visit, until it rides on your shoulder.": ["森の蜘蛛に生の鶏肉を与えよう。何度も通えば、肩に乗ってくる。", "숲거미에게 생닭고기를 줘라. 찾아갈 때마다 주다 보면 네 어깨에 올라탄다.", "给森林蜘蛛喂生鸡肉，一次又一次，直到它爬上你的肩头。", "給森林蜘蛛餵生雞肉，一次又一次，直到牠爬上你的肩頭。", "Cho một con nhện rừng ăn thịt gà sống, hết lần này đến lần khác, cho đến khi nó cưỡi trên vai ngươi.", "Beri laba-laba hutan daging ayam mentah, berkali-kali, sampai ia menumpang di bahumu.", "ป้อนเนื้อไก่ดิบให้แมงมุมป่า ครั้งแล้วครั้งเล่า จนกว่ามันจะขี่บนบ่าเจ้า", "Bir orman örümceğini tekrar tekrar çiğ tavukla besle, ta ki omzuna binene dek.", "Dale pollo crudo a una araña del bosque, visita tras visita, hasta que viaje en tu hombro.", "Dê frango cru a uma aranha da floresta, visita após visita, até ela andar no seu ombro.", "Кормите лесного паука сырой курятиной, раз за разом, пока он не сядет вам на плечо.", "Годуйте лісового павука сирою курятиною, раз за разом, доки він не сяде вам на плече."],
  "A forest spider the size of your hand, spinning as it walks. It leaves you the silk.": ["手のひらほどの森の蜘蛛。歩きながら糸を紡ぎ、絹を残していく。", "손바닥만 한 숲거미. 걸으면서 실을 잣고, 비단을 너에게 남긴다.", "一只手掌大小的森林蜘蛛，边走边吐丝。丝就留给你。", "一隻手掌大小的森林蜘蛛，邊走邊吐絲。絲就留給你。", "Một con nhện rừng to bằng bàn tay, vừa đi vừa nhả tơ. Nó để lại tơ cho ngươi.", "Laba-laba hutan sebesar telapak tangan, memintal sambil berjalan. Sutranya ia tinggalkan untukmu.", "แมงมุมป่าขนาดเท่าฝ่ามือ ชักใยไปพลางเดินไปพลาง มันทิ้งไหมไว้ให้เจ้า", "Avucun kadar bir orman örümceği, yürürken ağ örüyor. İpeği sana bırakır.", "Una araña del bosque del tamaño de tu mano, que hila mientras camina. Te deja la seda.", "Uma aranha da floresta do tamanho da sua mão, fiando enquanto anda. Deixa a seda para você.", "Лесной паук размером с ладонь, прядущий на ходу. Шёлк он оставляет вам.", "Лісовий павук завбільшки з долоню, що пряде на ходу. Шовк він лишає вам."],
  "Feed a glimmer moth starlight biscuits, visit after visit, in the Prismwild.": ["プリズムワイルドで、きらめき蛾に星明かりビスケットを与えよう。何度も通うこと。", "프리즘와일드에서 반짝나방에게 별빛 비스킷을 줘라. 찾아갈 때마다.", "在棱光荒野给微光蛾喂星光饼干，一次又一次。", "在稜光荒野給微光蛾餵星光餅乾，一次又一次。", "Cho một con bướm đêm lấp lánh ăn bánh quy ánh sao, hết lần này đến lần khác, ở Prismwild.", "Beri ngengat kilau biskuit cahaya bintang, berkali-kali, di Prismwild.", "ป้อนบิสกิตแสงดาวให้ผีเสื้อกลางคืนประกาย ครั้งแล้วครั้งเล่า ในพริซึมไวลด์", "Prismwild'da bir pırıltı güvesini tekrar tekrar yıldız ışığı bisküvisiyle besle.", "Dale galletas de luz de estrellas a una polilla de destello, visita tras visita, en el Prismwild.", "Dê biscoitos de luz das estrelas a uma mariposa cintilante, visita após visita, no Prismwild.", "Кормите мерцающую моль печеньем «звёздный свет», раз за разом, в Призмвайлде.", "Годуйте мерехтливу міль печивом «зоряне світло», раз за разом, у Призмвайлді."],
  "A glimmer moth that circles your head and dusts your shoulders violet. The dust is worth keeping.": ["頭の周りを飛び回り、肩を紫の粉で染めるきらめき蛾。その粉は取っておく価値がある。", "머리 주위를 맴돌며 어깨에 보랏빛 가루를 뿌리는 반짝나방. 그 가루는 모아 둘 만하다.", "一只绕着你脑袋飞、把你肩头撒成紫色的微光蛾。这些粉尘值得留着。", "一隻繞著你腦袋飛、把你肩頭撒成紫色的微光蛾。這些粉塵值得留著。", "Một con bướm đêm lấp lánh lượn quanh đầu ngươi và rắc bụi tím lên vai. Bụi ấy đáng giữ lại.", "Ngengat kilau yang berputar di sekitar kepalamu dan menaburi bahumu dengan debu ungu. Debunya layak disimpan.", "ผีเสื้อกลางคืนประกายที่บินวนรอบหัวเจ้าและโปรยผงสีม่วงบนบ่า ผงนั้นควรเก็บไว้", "Başının etrafında dönüp omuzlarını mora boyayan bir pırıltı güvesi. O toz saklamaya değer.", "Una polilla de destello que te ronda la cabeza y te empolva los hombros de violeta. Ese polvo vale la pena guardarlo.", "Uma mariposa cintilante que rodeia sua cabeça e cobre seus ombros de pó violeta. Vale a pena guardar o pó.", "Мерцающая моль кружит над головой и посыпает плечи фиолетовой пыльцой. Пыльцу стоит сохранить.", "Мерехтлива міль кружляє над головою й посипає плечі фіолетовим пилком. Пилок варто зберегти."],
  "Feed a jewelled peafowl grain, visit after visit, in Meghavan.": ["メガヴァンで、宝石クジャクに穀物を与えよう。何度も通うこと。", "메가반에서 보석공작에게 곡식을 줘라. 찾아갈 때마다.", "在梅加万给宝石孔雀喂谷子，一次又一次。", "在梅加萬給寶石孔雀餵穀子，一次又一次。", "Cho một con công châu báu ăn thóc, hết lần này đến lần khác, ở Meghavan.", "Beri merak permata biji-bijian, berkali-kali, di Meghavan.", "ป้อนเมล็ดพืชให้นกยูงอัญมณี ครั้งแล้วครั้งเล่า ในเมฆาวัน", "Meghavan'da mücevherli bir tavus kuşunu tekrar tekrar taneyle besle.", "Dale grano a un pavo real enjoyado, visita tras visita, en Meghavan.", "Dê grãos a um pavão cravejado, visita após visita, em Meghavan.", "Кормите самоцветного павлина зерном, раз за разом, в Мегаване.", "Годуйте самоцвітного павича зерном, раз за разом, у Мегавані."],
  "A peafowl whose tail glitters like a merchant's tray. Now and then it drops a feather, and lets you keep it.": ["尾が商人の盆のようにきらめくクジャク。ときどき羽根を落とし、あなたにくれる。", "꼬리가 상인의 쟁반처럼 반짝이는 공작. 이따금 깃털을 떨어뜨리고, 네가 갖게 해 준다.", "一只尾羽像商人的货盘一样闪闪发亮的孔雀。时不时掉下一根羽毛，让你留着。", "一隻尾羽像商人的貨盤一樣閃閃發亮的孔雀。時不時掉下一根羽毛，讓你留著。", "Một con công có đuôi lấp lánh như khay hàng của thương nhân. Thỉnh thoảng nó rụng một chiếc lông, và để ngươi giữ.", "Merak yang ekornya berkilau bak nampan saudagar. Sesekali ia menjatuhkan sehelai bulu, dan membiarkanmu menyimpannya.", "นกยูงที่หางระยิบระยับเหมือนถาดของพ่อค้า บางครั้งมันทำขนหล่น และยอมให้เจ้าเก็บไว้", "Kuyruğu bir tüccar tepsisi gibi parıldayan bir tavus kuşu. Arada bir tüy düşürür ve almana izin verir.", "Un pavo real cuya cola brilla como la bandeja de un mercader. De vez en cuando suelta una pluma y te deja quedártela.", "Um pavão cuja cauda brilha como a bandeja de um mercador. De vez em quando solta uma pena e deixa você ficar com ela.", "Павлин, чей хвост блестит, как поднос торговца. Время от времени он роняет перо и позволяет его забрать.", "Павич, чий хвіст блищить, як таця торговця. Час від часу він губить перо й дозволяє його забрати."],
  "Your adder's bite poisons it.": ["マムシの噛みつきが毒を回す。", "독사의 물기가 독을 퍼뜨린다.", "你的蝰蛇一口咬下，毒发了。", "你的蝰蛇一口咬下，毒發了。", "Vết cắn của rắn độc khiến nó trúng độc.", "Gigitan ular berbisamu meracuninya.", "รอยกัดของงูพิษทำให้มันติดพิษ", "Engereğinin ısırığı onu zehirliyor.", "La mordedura de tu víbora lo envenena.", "A picada da sua víbora o envenena.", "Укус вашей гадюки отравляет его.", "Укус вашої гадюки отруює його."],
  "Feed a marsh adder eggs or raw chicken, visit after visit.": ["沼マムシに卵か生の鶏肉を与えよう。何度も通うこと。", "늪독사에게 달걀이나 생닭고기를 줘라. 찾아갈 때마다.", "给沼泽蝰蛇喂蛋或生鸡肉，一次又一次。", "給沼澤蝰蛇餵蛋或生雞肉，一次又一次。", "Cho một con rắn đầm lầy ăn trứng hoặc thịt gà sống, hết lần này đến lần khác.", "Beri ular rawa telur atau daging ayam mentah, berkali-kali.", "ป้อนไข่หรือเนื้อไก่ดิบให้งูพิษหนองน้ำ ครั้งแล้วครั้งเล่า", "Bir bataklık engereğini tekrar tekrar yumurta ya da çiğ tavukla besle.", "Dale huevos o pollo crudo a una víbora de pantano, visita tras visita.", "Dê ovos ou frango cru a uma víbora do pântano, visita após visita.", "Кормите болотную гадюку яйцами или сырой курятиной, раз за разом.", "Годуйте болотяну гадюку яйцями чи сирою курятиною, раз за разом."],
  "A marsh adder that winds round your boot when it's cold. Its bite poisons what you fight.": ["寒いとブーツに巻きついてくる沼マムシ。その噛みつきは、あなたの敵に毒を回す。", "추우면 네 장화에 휘감기는 늪독사. 그 물기는 네가 싸우는 것에 독을 퍼뜨린다.", "一条天冷时就缠上你靴子的沼泽蝰蛇。它咬谁，谁就中毒。", "一條天冷時就纏上你靴子的沼澤蝰蛇。牠咬誰，誰就中毒。", "Một con rắn đầm lầy quấn quanh ủng ngươi khi trời lạnh. Vết cắn của nó làm kẻ thù ngươi trúng độc.", "Ular rawa yang melilit sepatumu saat dingin. Gigitannya meracuni musuhmu.", "งูพิษหนองน้ำที่พันรอบรองเท้าเจ้าเมื่ออากาศหนาว รอยกัดของมันทำให้ศัตรูของเจ้าติดพิษ", "Hava soğuyunca çizmene dolanan bir bataklık engereği. Isırığı dövüştüğün şeyi zehirler.", "Una víbora de pantano que se enrosca en tu bota cuando hace frío. Su mordedura envenena a lo que combates.", "Uma víbora do pântano que se enrola na sua bota quando faz frio. A picada envenena o que você enfrenta.", "Болотная гадюка, что обвивает ваш сапог, когда холодно. Её укус отравляет ваших врагов.", "Болотяна гадюка, що обвиває ваш чобіт, коли холодно. Її укус отруює ваших ворогів."],
  "Your pixie throws sparks!": ["ピクシーが火花を投げつける！", "픽시가 불꽃을 던진다!", "你的小精灵扔出火花！", "你的小精靈扔出火花！", "Tiên nhỏ của ngươi ném tia lửa!", "Peri kecilmu melempar percikan!", "พิกซี่ของเจ้าขว้างประกายไฟ!", "Perin kıvılcım fırlatıyor!", "¡Tu duendecillo lanza chispas!", "Sua fadinha atira faíscas!", "Ваш пикси мечет искры!", "Ваш піксі жбурляє іскри!"],
  "Beat a thistle pixie to its knees and spare it: it decides you're funny.": ["アザミのピクシーを打ち負かして見逃してやろう。あなたを面白いやつだと思ってくれる。", "엉겅퀴 픽시를 무릎 꿇린 뒤 살려 줘라. 너를 웃긴 녀석이라고 여긴다.", "把一只蓟草小精灵打得跪地求饶，再放过它：它会觉得你很有趣。", "把一隻薊草小精靈打得跪地求饒，再放過牠：牠會覺得你很有趣。", "Đánh một tiên gai quỳ gối rồi tha cho nó: nó sẽ thấy ngươi buồn cười.", "Kalahkan peri onak sampai bertekuk lutut lalu ampuni ia: ia akan menganggapmu lucu.", "ซัดพิกซี่หนามจนคุกเข่าแล้วไว้ชีวิตมัน มันจะเห็นว่าเจ้าตลกดี", "Bir deve dikeni perisini dize getir ve bağışla: seni komik bulur.", "Pon de rodillas a un duendecillo de cardo y perdónale: decide que eres gracioso.", "Ponha uma fadinha-do-cardo de joelhos e poupe-a: ela decide que você é engraçado.", "Поставьте чертополохового пикси на колени и пощадите: он решит, что вы забавный.", "Поставте будякового піксі на коліна й помилуйте: він вирішить, що ви кумедний."],
  "A thistle pixie who has decided you're funny. Mostly it throws sparks at what you fight. Mostly.": ["あなたを面白いと決めたアザミのピクシー。だいたいは、あなたの敵に火花を投げつける。だいたいは。", "너를 웃긴 녀석으로 정한 엉겅퀴 픽시. 대개는 네가 싸우는 것에 불꽃을 던진다. 대개는.", "一只觉得你很有趣的蓟草小精灵。它多半朝你的对手扔火花。多半。", "一隻覺得你很有趣的薊草小精靈。牠多半朝你的對手扔火花。多半。", "Một tiên gai đã quyết rằng ngươi buồn cười. Phần lớn thời gian nó ném tia lửa vào kẻ ngươi đánh. Phần lớn.", "Peri onak yang sudah memutuskan kau lucu. Biasanya ia melempar percikan ke musuhmu. Biasanya.", "พิกซี่หนามที่ตัดสินใจแล้วว่าเจ้าตลก ส่วนใหญ่มันขว้างประกายไฟใส่ศัตรูของเจ้า ส่วนใหญ่นะ", "Seni komik bulmaya karar vermiş bir deve dikeni perisi. Çoğunlukla dövüştüğün şeye kıvılcım atar. Çoğunlukla.", "Un duendecillo de cardo que ha decidido que eres gracioso. Casi siempre lanza chispas a lo que combates. Casi.", "Uma fadinha-do-cardo que decidiu que você é engraçado. Quase sempre atira faíscas no que você enfrenta. Quase.", "Чертополоховый пикси, решивший, что вы забавный. Обычно он мечет искры в ваших врагов. Обычно.", "Будяковий піксі, що вирішив, ніби ви кумедний. Зазвичай він жбурляє іскри у ваших ворогів. Зазвичай."],
  "Your wisp flares!": ["ウィスプが燃え上がる！", "도깨비불이 확 타오른다!", "你的光灵骤然闪耀！", "你的光靈驟然閃耀！", "Ma trơi của ngươi bùng sáng!", "Wisp-mu menyala terang!", "ภูตแสงของเจ้าลุกโชน!", "Işıltın parlıyor!", "¡Tu fuego fatuo destella!", "Seu fogo-fátuo resplandece!", "Ваш огонёк вспыхивает!", "Ваш вогник спалахує!"],
  "With Magic 40, offer a wisp glimmer dust: it comes to whoever can speak its light.": ["魔法40で、ウィスプにきらめきの粉を差し出そう。その光を語れる者のもとへ来る。", "마법 40이 되면 도깨비불에게 반짝이 가루를 바쳐라. 제 빛을 말할 줄 아는 이에게 온다.", "魔法达到 40 后，向光灵献上微光粉尘：它会来到能说出它光芒之语的人身边。", "魔法達到 40 後，向光靈獻上微光粉塵：牠會來到能說出牠光芒之語的人身邊。", "Với Phép thuật 40, dâng bụi lấp lánh cho một ma trơi: nó đến với ai biết nói thứ ánh sáng của nó.", "Dengan Sihir 40, persembahkan debu kilau pada wisp: ia datang pada siapa pun yang bisa mengucapkan cahayanya.", "เมื่อเวทมนตร์ถึง 40 ให้ถวายผงประกายแก่ภูตแสง มันจะมาหาผู้ที่พูดภาษาแสงของมันได้", "Büyü 40 ile bir ışıltıya pırıltı tozu sun: ışığını konuşabilen kişiye gelir.", "Con Magia 40, ofrece polvo de destello a un fuego fatuo: acude a quien sabe hablar su luz.", "Com Magia 40, ofereça pó cintilante a um fogo-fátuo: ele vem a quem sabe falar a sua luz.", "С Магией 40 предложите огоньку мерцающую пыльцу: он приходит к тому, кто умеет говорить на языке его света.", "З Магією 40 запропонуйте вогнику мерехтливий пилок: він приходить до того, хто вміє говорити мовою його світла."],
  "A wisp that drifts at your shoulder, changing colour. Underground, it lights the way; in a fight, it flares.": ["色を変えながら肩のそばを漂うウィスプ。地下では道を照らし、戦いでは燃え上がる。", "색을 바꾸며 네 어깨 곁을 떠다니는 도깨비불. 지하에서는 길을 밝히고, 싸움에서는 확 타오른다.", "一个在你肩旁飘荡、不断变色的光灵。在地下它为你照路；在战斗中它骤然闪耀。", "一個在你肩旁飄盪、不斷變色的光靈。在地下牠為你照路；在戰鬥中牠驟然閃耀。", "Một ma trơi trôi bên vai ngươi, đổi màu liên tục. Dưới lòng đất, nó soi đường; khi chiến đấu, nó bùng sáng.", "Wisp yang melayang di bahumu, berganti warna. Di bawah tanah ia menerangi jalan; dalam pertarungan ia menyala.", "ภูตแสงที่ลอยข้างบ่าเจ้า เปลี่ยนสีไปมา ใต้ดินมันส่องทาง ยามต่อสู้มันลุกโชน", "Omzunun yanında süzülen, renk değiştiren bir ışıltı. Yeraltında yolu aydınlatır; dövüşte parlar.", "Un fuego fatuo que flota junto a tu hombro, cambiando de color. Bajo tierra alumbra el camino; en combate, destella.", "Um fogo-fátuo que flutua junto ao seu ombro, mudando de cor. No subterrâneo ilumina o caminho; na luta, resplandece.", "Огонёк, что плывёт у вашего плеча, меняя цвет. Под землёй он освещает путь, в бою вспыхивает.", "Вогник, що пливе біля вашого плеча, змінюючи колір. Під землею він освітлює шлях, у бою спалахує."],
  "Feed a tomb beetle bread or raw beef, visit after visit, in Kharaveth.": ["カラヴェスで、墓守甲虫にパンか生の牛肉を与えよう。何度も通うこと。", "카라베스에서 무덤딱정벌레에게 빵이나 생소고기를 줘라. 찾아갈 때마다.", "在卡拉维斯给墓穴甲虫喂面包或生牛肉，一次又一次。", "在卡拉維斯給墓穴甲蟲餵麵包或生牛肉，一次又一次。", "Cho một con bọ lăng mộ ăn bánh mì hoặc thịt bò sống, hết lần này đến lần khác, ở Kharaveth.", "Beri kumbang makam roti atau daging sapi mentah, berkali-kali, di Kharaveth.", "ป้อนขนมปังหรือเนื้อวัวดิบให้ด้วงสุสาน ครั้งแล้วครั้งเล่า ในคาราเวธ", "Kharaveth'te bir mezar böceğini tekrar tekrar ekmek ya da çiğ sığır etiyle besle.", "Dale pan o ternera cruda a un escarabajo de tumba, visita tras visita, en Kharaveth.", "Dê pão ou carne crua a um besouro-de-tumba, visita após visita, em Kharaveth.", "Кормите гробничного жука хлебом или сырой говядиной, раз за разом, в Харавете.", "Годуйте гробничного жука хлібом чи сирою яловичиною, раз за разом, у Хараветі."],
  "A tomb beetle as big as a loaf, shell like old bronze. It digs, and sometimes what it digs up is gold.": ["パンほどもある墓守甲虫。殻は古い青銅のよう。掘っては、ときどき金を掘り当てる。", "빵 한 덩이만 한 무덤딱정벌레. 껍데기는 오래된 청동 같다. 땅을 파는데, 가끔 파낸 것이 황금이다.", "一只面包那么大的墓穴甲虫，甲壳像古铜。它会挖，有时挖出来的是金子。", "一隻麵包那麼大的墓穴甲蟲，甲殼像古銅。牠會挖，有時挖出來的是金子。", "Một con bọ lăng mộ to bằng ổ bánh mì, vỏ như đồng cổ. Nó đào bới, và đôi khi thứ nó đào lên là vàng.", "Kumbang makam sebesar roti, cangkangnya bagai perunggu tua. Ia menggali, dan kadang yang tergali adalah emas.", "ด้วงสุสานตัวโตเท่าก้อนขนมปัง กระดองเหมือนสำริดเก่า มันขุด และบางครั้งสิ่งที่ขุดได้ก็คือทอง", "Bir somun büyüklüğünde, kabuğu eski tunç gibi bir mezar böceği. Kazar, bazen kazıp çıkardığı altındır.", "Un escarabajo de tumba grande como una hogaza, de caparazón como bronce viejo. Escarba, y a veces lo que saca es oro.", "Um besouro-de-tumba do tamanho de um pão, casca de bronze antigo. Ele cava, e às vezes o que desenterra é ouro.", "Гробничный жук величиной с буханку, панцирь как старая бронза. Он роет, и порой вырывает золото.", "Гробничний жук завбільшки з буханець, панцир як стара бронза. Він риє, і часом вириває золото."],
  "Your serpent's bite poisons it.": ["コブラの噛みつきが毒を回す。", "코브라의 물기가 독을 퍼뜨린다.", "你的眼镜蛇一口咬下，毒发了。", "你的眼鏡蛇一口咬下，毒發了。", "Vết cắn của rắn hổ mang khiến nó trúng độc.", "Gigitan ular kobramu meracuninya.", "รอยกัดของงูเห่าทำให้มันติดพิษ", "Kobranın ısırığı onu zehirliyor.", "La mordedura de tu serpiente lo envenena.", "A picada da sua serpente o envenena.", "Укус вашей змеи отравляет его.", "Укус вашої змії отруює його."],
  "Play a charmer's flute to a hooded serpent, in Meghavan.": ["メガヴァンで、フードコブラに蛇使いの笛を吹いて聞かせよう。", "메가반에서 두건뱀에게 뱀 부리는 피리를 불어 줘라.", "在梅加万，对着眼镜蛇吹奏弄蛇人的笛子。", "在梅加萬，對著眼鏡蛇吹奏弄蛇人的笛子。", "Thổi sáo dụ rắn cho một con rắn hổ mang, ở Meghavan.", "Mainkan seruling pawang ular untuk ular kobra, di Meghavan.", "เป่าขลุ่ยหมองูให้งูเห่าฟัง ในเมฆาวัน", "Meghavan'da bir kukuletalı yılana yılan oynatıcısı flütü çal.", "Toca una flauta de encantador a una serpiente de capucha, en Meghavan.", "Toque uma flauta de encantador para uma serpente-de-capuz, em Meghavan.", "Сыграйте на флейте заклинателя капюшонной змее, в Мегаване.", "Зіграйте на флейті заклинача каптуровій змії, у Мегавані."],
  "A hooded serpent that rises when you play and sways when you stop. Its bite is far worse than an adder's.": ["笛を吹けば鎌首をもたげ、やめれば揺れるフードコブラ。その噛みつきはマムシよりずっと危険だ。", "피리를 불면 고개를 들고, 멈추면 몸을 흔드는 두건뱀. 그 물기는 독사보다 훨씬 지독하다.", "一条你吹笛就昂首、你停下就摇摆的眼镜蛇。它的咬伤比蝰蛇厉害得多。", "一條你吹笛就昂首、你停下就搖擺的眼鏡蛇。牠的咬傷比蝰蛇厲害得多。", "Một con rắn hổ mang ngóc lên khi ngươi thổi và lắc lư khi ngươi dừng. Vết cắn của nó độc hơn rắn đầm lầy nhiều.", "Ular kobra yang tegak saat kau bermain dan bergoyang saat kau berhenti. Gigitannya jauh lebih parah dari ular berbisa biasa.", "งูเห่าที่ชูคอเมื่อเจ้าเป่าและโยกตัวเมื่อเจ้าหยุด รอยกัดของมันร้ายกว่างูพิษมาก", "Sen çalınca doğrulan, durunca salınan bir kukuletalı yılan. Isırığı bir engereğinkinden çok daha kötüdür.", "Una serpiente de capucha que se alza cuando tocas y se mece cuando paras. Su mordedura es mucho peor que la de una víbora.", "Uma serpente-de-capuz que se ergue quando você toca e balança quando para. A picada é bem pior que a de uma víbora.", "Капюшонная змея, что поднимается, когда вы играете, и покачивается, когда перестаёте. Её укус куда хуже гадючьего.", "Каптурова змія, що здіймається, коли ви граєте, і погойдується, коли перестаєте. Її укус куди гірший за гадючий."],
  "Know the glimmer stag's habitat and its temper (Pursuance), then feed one a starlight biscuit.": ["きらめき鹿の生息地と気性を知り（追跡術）、それから星明かりビスケットを与えよう。", "반짝사슴의 서식지와 기질을 알아낸 뒤(추적술), 별빛 비스킷을 먹여라.", "先了解微光雄鹿的栖息地和习性（追猎），再喂它一块星光饼干。", "先了解微光雄鹿的棲息地和習性（追獵），再餵牠一塊星光餅乾。", "Biết nơi ở và tính khí của hươu lấp lánh (Truy lùng), rồi cho nó ăn một bánh quy ánh sao.", "Ketahui habitat dan watak rusa kilau (Perburuan), lalu beri ia biskuit cahaya bintang.", "รู้ถิ่นที่อยู่และนิสัยของกวางประกาย (การไล่ล่า) แล้วป้อนบิสกิตแสงดาวให้มัน", "Pırıltı geyiğinin yaşam alanını ve huyunu öğren (Takip), sonra ona bir yıldız ışığı bisküvisi ver.", "Conoce el hábitat y el temperamento del ciervo de destello (Rastreo) y luego dale una galleta de luz de estrellas.", "Conheça o habitat e o temperamento do cervo cintilante (Rastreio) e depois dê a ele um biscoito de luz das estrelas.", "Узнайте, где обитает мерцающий олень и каков его нрав (Выслеживание), затем угостите его печеньем «звёздный свет».", "Дізнайтеся, де живе мерехтливий олень і яка в нього вдача (Вистежування), потім пригостіть його печивом «зоряне світло»."],
  "A white stag with antlers of violet crystal, walking at your side. The road all but runs itself.": ["紫水晶の角を持つ白い鹿が、あなたの傍らを歩く。道のりはほとんど勝手に進んでいく。", "보랏빛 수정 뿔을 단 흰 사슴이 네 곁을 걷는다. 길이 거의 저절로 줄어든다.", "一头长着紫水晶鹿角的白鹿，走在你身旁。路几乎自己就走完了。", "一頭長著紫水晶鹿角的白鹿，走在你身旁。路幾乎自己就走完了。", "Một con hươu trắng với gạc pha lê tím, đi bên cạnh ngươi. Con đường gần như tự trôi đi.", "Rusa putih bertanduk kristal ungu, berjalan di sisimu. Jalan seakan menempuh dirinya sendiri.", "กวางขาวเขาผลึกสีม่วง เดินอยู่ข้างเจ้า ทางแทบจะเดินไปเอง", "Mor kristal boynuzlu beyaz bir geyik, yanında yürüyor. Yol neredeyse kendi kendine kısalıyor.", "Un ciervo blanco de astas de cristal violeta, caminando a tu lado. El camino casi se recorre solo.", "Um cervo branco de galhadas de cristal violeta, andando ao seu lado. O caminho quase se percorre sozinho.", "Белый олень с рогами из фиолетового кристалла шагает рядом с вами. Дорога почти сама бежит под ноги.", "Білий олень із рогами з фіолетового кришталю крокує поруч із вами. Дорога майже сама біжить під ноги."],
  "Your golem crushes it!": ["ゴーレムが叩き潰す！", "골렘이 짓뭉갠다!", "你的魔像一把将它碾碎！", "你的魔像一把將它碾碎！", "Người đá của ngươi nghiền nát nó!", "Golemmu meremukkannya!", "โกเลมของเจ้าบดขยี้มัน!", "Golemin onu eziyor!", "¡Tu gólem lo aplasta!", "Seu golem o esmaga!", "Ваш голем сокрушает его!", "Ваш голем розчавлює його!"],
  "Beat a shard golem to its knees and spare it: it follows whatever beat it.": ["欠片のゴーレムを打ち負かして見逃してやろう。自分を負かした者についてくる。", "파편 골렘을 무릎 꿇린 뒤 살려 줘라. 자신을 이긴 자를 따른다.", "把一只碎晶魔像打得跪地，再放过它：它会追随打败它的人。", "把一隻碎晶魔像打得跪地，再放過牠：牠會追隨打敗牠的人。", "Đánh một người đá mảnh vỡ quỳ gối rồi tha cho nó: nó theo kẻ đã đánh bại nó.", "Kalahkan golem serpihan sampai bertekuk lutut lalu ampuni ia: ia mengikuti siapa pun yang mengalahkannya.", "ซัดโกเลมเศษผลึกจนคุกเข่าแล้วไว้ชีวิตมัน มันจะติดตามผู้ที่เอาชนะมัน", "Bir kırık golemini dize getir ve bağışla: onu yeneni izler.", "Pon de rodillas a un gólem de esquirlas y perdónale: sigue a quien lo haya vencido.", "Ponha um golem de estilhaços de joelhos e poupe-o: ele segue quem o venceu.", "Поставьте осколочного голема на колени и пощадите: он пойдёт за тем, кто его одолел.", "Поставте уламкового голема на коліна й помилуйте: він піде за тим, хто його здолав."],
  "A heap of violet crystal that walks where you walk and stands in front of whatever's at you.": ["あなたの行く所を歩き、あなたに向かってくるものの前に立ちはだかる紫水晶の塊。", "네가 가는 곳을 함께 걷고, 너에게 덤비는 것 앞을 막아서는 보랏빛 수정 덩어리.", "一堆紫水晶，你走到哪儿它跟到哪儿，冲你来的东西都得先过它这关。", "一堆紫水晶，你走到哪兒牠跟到哪兒，衝你來的東西都得先過牠這關。", "Một đống pha lê tím đi theo ngươi khắp nơi và đứng chắn trước bất cứ thứ gì lao vào ngươi.", "Gundukan kristal ungu yang berjalan ke mana kau berjalan dan berdiri di depan apa pun yang menyerangmu.", "กองผลึกสีม่วงที่เดินไปทุกที่ที่เจ้าไป และยืนขวางหน้าทุกสิ่งที่พุ่งเข้าหาเจ้า", "Nereye yürüsen oraya yürüyen ve sana saldıran her şeyin önüne dikilen bir mor kristal yığını.", "Un montón de cristal violeta que camina donde tú caminas y se planta delante de lo que vaya a por ti.", "Um monte de cristal violeta que anda onde você anda e se põe na frente do que vier contra você.", "Груда фиолетового кристалла, что ходит, где ходите вы, и встаёт перед всем, что на вас нападает.", "Купа фіолетового кришталю, що ходить, де ходите ви, і стає перед усім, що на вас нападає."],
  "Drake": ["ドレイク", "드레이크", "幼龙", "幼龍", "Rồng con", "Drake", "เดรก", "Ejderha yavrusu", "Draco", "Draco", "Дрейк", "Дрейк"],
  "Your drake breathes fire!": ["ドレイクが炎を吐く！", "드레이크가 불을 뿜는다!", "你的幼龙喷出烈焰！", "你的幼龍噴出烈焰！", "Rồng con của ngươi phun lửa!", "Drake-mu menyemburkan api!", "เดรกของเจ้าพ่นไฟ!", "Ejderha yavrun ateş püskürüyor!", "¡Tu draco escupe fuego!", "Seu draco cospe fogo!", "Ваш дрейк выдыхает пламя!", "Ваш дрейк видихає полум'я!"],
  "Find a speckled drake egg (the drakes drop them, rarely) and have a beastkeeper keep it warm for half an hour. Whoever's waiting when it hatches is its mother.": ["まだら模様のドレイクの卵を見つけ（ドレイクがまれに落とす）、獣使いに30分温めてもらおう。孵るとき待っていた者が、その母親になる。", "얼룩무늬 드레이크 알을 찾아(드레이크가 드물게 떨어뜨린다) 조련사에게 30분 동안 따뜻하게 맡겨라. 알이 깰 때 기다리던 이가 그 어미가 된다.", "找到一枚斑点幼龙蛋（幼龙偶尔会掉落），请驯兽人替你保温半个小时。破壳时守在旁边的人就是它的母亲。", "找到一枚斑點幼龍蛋（幼龍偶爾會掉落），請馴獸人替你保溫半個小時。破殼時守在旁邊的人就是牠的母親。", "Tìm một quả trứng rồng đốm (rồng con hiếm khi đánh rơi) và nhờ người nuôi thú ủ ấm nửa giờ. Ai đang chờ khi trứng nở sẽ là mẹ nó.", "Temukan telur drake berbintik (para drake kadang menjatuhkannya) dan minta penjinak menghangatkannya setengah jam. Siapa yang menunggu saat menetas adalah induknya.", "หาไข่เดรกลายจุด (เดรกทำตกบ้าง นานๆ ที) แล้วให้ผู้เลี้ยงสัตว์ช่วยกกไว้ครึ่งชั่วโมง ใครรออยู่ตอนไข่ฟักคือแม่ของมัน", "Benekli bir ejderha yumurtası bul (ejderha yavruları nadiren düşürür) ve bir bakıcıya yarım saat sıcak tutturt. Yumurta çatladığında kim bekliyorsa onun annesidir.", "Encuentra un huevo de draco moteado (los dracos los sueltan, rara vez) y pide a un cuidador de bestias que lo mantenga caliente media hora. Quien esté esperando cuando eclosione será su madre.", "Encontre um ovo de draco pintado (os dracos deixam cair, raramente) e peça a um tratador que o mantenha quente por meia hora. Quem estiver esperando quando chocar será a mãe dele.", "Найдите пятнистое яйцо дрейка (дрейки изредка его роняют) и попросите зверовода полчаса держать его в тепле. Кто ждёт, когда оно треснет, тот ему и мать.", "Знайдіть плямисте яйце дрейка (дрейки зрідка його гублять) і попросіть звірівника пів години тримати його в теплі. Хто чекає, коли воно трісне, той йому й мати."],
  "A drake you raised from the egg. It breathes fire on what you fight, and on whatever's standing next to it.": ["卵から育てたドレイク。あなたの敵に、そしてその隣に立つものにも炎を吐く。", "알에서부터 키운 드레이크. 네가 싸우는 것에, 그리고 그 옆에 선 것에도 불을 뿜는다.", "一头你从蛋里养大的幼龙。它朝你的对手喷火，连旁边站着的也不放过。", "一頭你從蛋裡養大的幼龍。牠朝你的對手噴火，連旁邊站著的也不放過。", "Một con rồng con ngươi nuôi từ trứng. Nó phun lửa vào kẻ ngươi đánh, và cả thứ đứng cạnh nó.", "Drake yang kau besarkan dari telur. Ia menyemburkan api ke musuhmu, dan ke apa pun yang berdiri di sebelahnya.", "เดรกที่เจ้าเลี้ยงมาตั้งแต่ในไข่ มันพ่นไฟใส่ศัตรูของเจ้า และใส่ทุกสิ่งที่ยืนอยู่ข้างๆ", "Yumurtadan büyüttüğün bir ejderha yavrusu. Dövüştüğün şeye ve yanında duran her şeye ateş püskürür.", "Un draco que criaste desde el huevo. Escupe fuego sobre lo que combates y sobre lo que tenga al lado.", "Um draco que você criou desde o ovo. Cospe fogo no que você enfrenta e no que estiver ao lado.", "Дрейк, которого вы вырастили из яйца. Он дышит огнём на ваших врагов и на всё, что стоит рядом.", "Дрейк, якого ви виростили з яйця. Він дихає вогнем на ваших ворогів і на все, що стоїть поруч."],
  "Trained": ["訓練済み", "훈련됨", "受过训练", "受過訓練", "Đã huấn luyện", "Terlatih", "ฝึกแล้ว", "Eğitimli", "Adiestrado", "Treinado", "Обученный", "Навчений"],
  "Well trained": ["よく訓練された", "잘 훈련됨", "训练有素", "訓練有素", "Huấn luyện kỹ", "Terlatih baik", "ฝึกมาดี", "Eğitimi sağlam", "Bien adiestrado", "Bem treinado", "Хорошо обученный", "Добре навчений"],
  "Masterful": ["名人級", "명인급", "炉火纯青", "爐火純青", "Bậc thầy", "Piawai", "ชั้นครู", "Ustaca", "Magistral", "Magistral", "Мастерский", "Майстерний"],
  "Legendary": ["伝説級", "전설급", "传奇", "傳奇", "Huyền thoại", "Legendaris", "ระดับตำนาน", "Efsanevi", "Legendario", "Lendário", "Легендарный", "Легендарний"],
  "Your hen has laid an egg. You pocket it.": ["雌鶏が卵を産んだ。ポケットにしまう。", "암탉이 알을 낳았다. 주머니에 넣는다.", "你的母鸡下了个蛋。你揣进兜里。", "你的母雞下了個蛋。你揣進兜裡。", "Gà mái của ngươi đẻ một quả trứng. Ngươi bỏ vào túi.", "Ayam betinamu bertelur. Kau mengantonginya.", "แม่ไก่ของเจ้าออกไข่ เจ้าเก็บใส่กระเป๋า", "Tavuğun bir yumurta yumurtladı. Cebine atıyorsun.", "Tu gallina ha puesto un huevo. Te lo guardas.", "Sua galinha botou um ovo. Você o guarda.", "Ваша курица снесла яйцо. Вы прячете его в карман.", "Ваша курка знесла яйце. Ви ховаєте його до кишені."],
  "Your sheep is woolly enough to shear: you take the wool.": ["羊の毛が刈れるほど伸びた。羊毛をいただく。", "양의 털이 깎을 만큼 자랐다. 양털을 챙긴다.", "你的羊毛长得能剪了：你剪下了羊毛。", "你的羊毛長得能剪了：你剪下了羊毛。", "Cừu của ngươi đủ lông để xén: ngươi lấy lông cừu.", "Dombamu sudah cukup berbulu untuk dicukur: kau mengambil wolnya.", "แกะของเจ้าขนยาวพอจะตัดแล้ว เจ้าเก็บขนแกะ", "Koyunun kırkılacak kadar yünlendi: yünü alıyorsun.", "Tu oveja tiene lana de sobra para esquilar: te quedas la lana.", "Sua ovelha já tem lã para tosquiar: você fica com a lã.", "Ваша овца обросла достаточно для стрижки: вы забираете шерсть.", "Ваша вівця обросла досить для стрижки: ви забираєте вовну."],
  "Your milk cow lets you fill a bucket.": ["乳牛がバケツを満たさせてくれる。", "젖소가 양동이를 채우게 해 준다.", "你的奶牛让你挤满了一桶奶。", "你的乳牛讓你擠滿了一桶奶。", "Bò sữa của ngươi để ngươi vắt đầy một xô.", "Sapi perahmu membiarkanmu mengisi seember.", "วัวนมของเจ้ายอมให้เจ้ารีดนมจนเต็มถัง", "Süt ineğin bir kova doldurmana izin veriyor.", "Tu vaca lechera te deja llenar un cubo.", "Sua vaca leiteira deixa você encher um balde.", "Ваша дойная корова даёт вам наполнить ведро.", "Ваша дійна корова дає вам наповнити відро."],
  "Your silk spider has spun a sheet of silk.": ["絹蜘蛛が絹を一枚紡いだ。", "비단거미가 비단 한 필을 자아냈다.", "你的丝蛛织出了一匹丝绸。", "你的絲蛛織出了一匹絲綢。", "Nhện tơ của ngươi đã dệt một tấm lụa.", "Laba-laba sutramu telah memintal selembar sutra.", "แมงมุมไหมของเจ้าชักใยได้ผ้าไหมหนึ่งผืน", "İpek örümceğin bir parça ipek ördü.", "Tu araña de seda ha hilado una pieza de seda.", "Sua aranha-da-seda fiou uma peça de seda.", "Ваш шелковый паук спрял лоскут шёлка.", "Ваш шовковий павук спряв клапоть шовку."],
  "Your glimmer moth has dusted you violet: you shake it into a pouch.": ["きらめき蛾があなたを紫の粉まみれにした。袋に払い落とす。", "반짝나방이 너를 보랏빛 가루로 뒤덮었다. 주머니에 털어 담는다.", "你的微光蛾把你撒成了紫色：你把粉抖进小袋里。", "你的微光蛾把你撒成了紫色：你把粉抖進小袋裡。", "Bướm đêm lấp lánh rắc bụi tím khắp người ngươi: ngươi giũ nó vào túi.", "Ngengat kilaumu menaburimu dengan debu ungu: kau mengibaskannya ke kantong.", "ผีเสื้อกลางคืนประกายโปรยผงม่วงใส่เจ้า เจ้าเคาะผงลงถุง", "Pırıltı güven seni mora buladı: tozu bir keseye silkeliyorsun.", "Tu polilla de destello te ha empolvado de violeta: lo sacudes en una bolsita.", "Sua mariposa cintilante cobriu você de violeta: você sacode o pó numa bolsinha.", "Ваша мерцающая моль осыпала вас фиолетовым: вы стряхиваете пыльцу в мешочек.", "Ваша мерехтлива міль обсипала вас фіолетовим: ви струшуєте пилок у торбинку."],
  "Your peafowl drops a jewelled feather, and lets you keep it.": ["クジャクが宝石の羽根を落とし、あなたにくれた。", "공작이 보석 깃털을 떨어뜨리고, 네가 갖게 해 준다.", "你的孔雀掉下一根宝石羽毛，让你留着。", "你的孔雀掉下一根寶石羽毛，讓你留著。", "Con công của ngươi rụng một chiếc lông châu báu, và để ngươi giữ.", "Merakmu menjatuhkan bulu permata, dan membiarkanmu menyimpannya.", "นกยูงของเจ้าทำขนอัญมณีหล่น และยอมให้เจ้าเก็บไว้", "Tavus kuşun mücevherli bir tüy düşürüyor ve almana izin veriyor.", "Tu pavo real suelta una pluma enjoyada y te deja quedártela.", "Seu pavão solta uma pena cravejada e deixa você ficar com ela.", "Ваш павлин роняет самоцветное перо и позволяет его забрать.", "Ваш павич губить самоцвітне перо й дозволяє його забрати."],
  "Your tomb beetle has dug up a gold scarab.": ["墓守甲虫が金のスカラベを掘り当てた。", "무덤딱정벌레가 황금 풍뎅이를 파냈다.", "你的墓穴甲虫挖出了一只金圣甲虫。", "你的墓穴甲蟲挖出了一隻金聖甲蟲。", "Bọ lăng mộ của ngươi đào lên một con bọ hung vàng.", "Kumbang makammu menggali seekor kumbang skarab emas.", "ด้วงสุสานของเจ้าขุดเจอแมลงสคารับทองคำ", "Mezar böceğin bir altın bokböceği kazıp çıkardı.", "Tu escarabajo de tumba ha desenterrado un escarabajo de oro.", "Seu besouro-de-tumba desenterrou um escaravelho de ouro.", "Ваш гробничный жук выкопал золотого скарабея.", "Ваш гробничний жук викопав золотого скарабея."],
  "{x} brings you something.": ["{x}が何か持ってきた。", "{x}이(가) 뭔가를 가져온다.", "{x}给你带来了点东西。", "{x}給你帶來了點東西。", "{x} mang đến cho ngươi thứ gì đó.", "{x} membawakanmu sesuatu.", "{x}นำบางอย่างมาให้เจ้า", "{x} sana bir şey getiriyor.", "{x} te trae algo.", "{x} traz algo para você.", "{x} приносит вам кое-что.", "{x} приносить вам дещо."],
  "You need a Beastkeeping level of {n} to train a companion that far.": ["相棒をそこまで訓練するには獣使いレベル{n}が必要。", "동료를 거기까지 훈련하려면 조련술 레벨 {n}이 필요하다.", "要把伙伴训练到那一步，需要驯兽等级 {n}。", "要把夥伴訓練到那一步，需要馴獸等級 {n}。", "Ngươi cần cấp Thuần thú {n} để huấn luyện bạn đồng hành tới mức đó.", "Kau butuh level Penjinakan {n} untuk melatih pendamping sejauh itu.", "เจ้าต้องมีระดับการเลี้ยงสัตว์ {n} จึงจะฝึกคู่หูได้ถึงขั้นนั้น", "Bir yoldaşı o kadar eğitmek için Hayvan bakıcılığı seviyen {n} olmalı.", "Necesitas Doma de bestias {n} para adiestrar tanto a un compañero.", "Você precisa de Doma de feras {n} para treinar um companheiro até aí.", "Чтобы так далеко обучить спутника, нужно Звероводство {n}.", "Щоб так далеко навчити супутника, потрібне Звірівництво {n}."],
  "That training costs {n} Frens.": ["その訓練は{n}フレンかかる。", "그 훈련은 {n} 프렌이 든다.", "那项训练要 {n} 友币。", "那項訓練要 {n} 友幣。", "Khóa huấn luyện đó tốn {n} Fren.", "Pelatihan itu seharga {n} Fren.", "การฝึกนั้นใช้ {n} เฟรน", "O eğitim {n} Fren tutar.", "Ese adiestramiento cuesta {n} Frens.", "Esse treinamento custa {n} Frens.", "Это обучение стоит {n} френов.", "Це навчання коштує {n} френів."],
  "{x} begins its training. Work with it: {n} deeds done together (fights won, what it brings in, brushing it down, the road).": ["{x}の訓練が始まった。一緒に{n}回の務めを果たそう（勝った戦い、持ってくる収穫、ブラッシング、旅路）。", "{x}의 훈련이 시작됐다. 함께 {n}번의 일을 해내라 (이긴 싸움, 가져오는 것, 빗질, 길).", "{x}开始受训了。和它一起完成 {n} 件事（打赢的仗、它带回的东西、给它刷毛、一起赶路）。", "{x}開始受訓了。和牠一起完成 {n} 件事（打贏的仗、牠帶回的東西、給牠刷毛、一起趕路）。", "{x} bắt đầu huấn luyện. Hãy cùng nó làm {n} việc (thắng trận, thứ nó mang về, chải lông, đường đi).", "{x} memulai pelatihannya. Bekerjalah bersamanya: {n} perbuatan bersama (pertarungan dimenangkan, hasil yang dibawanya, menyikatnya, perjalanan).", "{x}เริ่มการฝึกแล้ว ทำงานร่วมกับมัน: ภารกิจ {n} อย่างที่ทำด้วยกัน (ชนะการต่อสู้ ของที่มันนำมา แปรงขน การเดินทาง)", "{x} eğitimine başladı. Onunla çalış: birlikte {n} iş (kazanılan dövüşler, getirdikleri, tımar, yol).", "{x} empieza su adiestramiento. Trabaja con él: {n} hazañas juntos (combates ganados, lo que trae, cepillarlo, el camino).", "{x} começa o treinamento. Trabalhe com ele: {n} feitos juntos (lutas vencidas, o que ele traz, escová-lo, a estrada).", "{x} начинает обучение. Работайте вместе: {n} дел сообща (выигранные бои, то, что он приносит, чистка, дорога).", "{x} починає навчання. Працюйте разом: {n} справ спільно (виграні бої, те, що він приносить, чищення, дорога)."],
  "{x}'s coat is as good as it'll get. Later.": ["{x}の毛並みはこれ以上ないほど整っている。また後で。", "{x}의 털은 더할 나위 없이 좋다. 나중에.", "{x}的毛已经再好不过了。过会儿再说。", "{x}的毛已經再好不過了。過會兒再說。", "Bộ lông của {x} đã đẹp hết mức rồi. Để sau.", "Bulu {x} sudah sebaik-baiknya. Nanti saja.", "ขนของ{x}ดีที่สุดแล้ว ไว้ทีหลัง", "{x} tüyü olabileceği kadar güzel. Sonra.", "El pelaje de {x} no puede estar mejor. Luego.", "A pelagem de {x} não pode ficar melhor. Depois.", "Шерсть {x} лучше уже не станет. Позже.", "Шерсть {x} кращою вже не стане. Пізніше."],
  "You brush {x} down. It leans into the brush.": ["{x}にブラシをかける。気持ちよさそうに身を寄せてくる。", "{x}를 빗질해 준다. 빗에 몸을 기댄다.", "你给{x}刷了刷毛。它往刷子上靠。", "你給{x}刷了刷毛。牠往刷子上靠。", "Ngươi chải lông cho {x}. Nó dựa vào bàn chải.", "Kau menyikat {x}. Ia bersandar ke sikat.", "เจ้าแปรงขนให้{x} มันเอนตัวเข้าหาแปรง", "{x} tımar ediyorsun. Fırçaya yaslanıyor.", "Cepillas a {x}. Se apoya contra el cepillo.", "Você escova {x}. Ele se encosta na escova.", "Вы чистите {x}. Он подставляется под щётку.", "Ви чистите {x}. Він підставляється під щітку."],
  "It flickers, and drifts away. (Magic 40: it comes to whoever can speak its light.)": ["揺らめいて、漂い去っていく。（魔法40：その光を語れる者のもとへ来る。）", "깜박이더니 떠내려가 버린다. (마법 40: 제 빛을 말할 줄 아는 이에게 온다.)", "它闪了闪，飘走了。（魔法 40：它会来到能说出它光芒之语的人身边。）", "牠閃了閃，飄走了。（魔法 40：牠會來到能說出牠光芒之語的人身邊。）", "Nó lập lòe, rồi trôi đi. (Phép thuật 40: nó đến với ai biết nói thứ ánh sáng của nó.)", "Ia berkedip, lalu melayang pergi. (Sihir 40: ia datang pada siapa pun yang bisa mengucapkan cahayanya.)", "มันกะพริบ แล้วลอยจากไป (เวทมนตร์ 40: มันจะมาหาผู้ที่พูดภาษาแสงของมันได้)", "Titreşiyor ve süzülüp gidiyor. (Büyü 40: ışığını konuşabilen kişiye gelir.)", "Parpadea y se aleja flotando. (Magia 40: acude a quien sabe hablar su luz.)", "Ele tremeluz e se afasta. (Magia 40: vem a quem sabe falar a sua luz.)", "Он мерцает и уплывает прочь. (Магия 40: он приходит к тому, кто умеет говорить на языке его света.)", "Він мерехтить і відпливає геть. (Магія 40: він приходить до того, хто вміє говорити мовою його світла.)"],
  "It's watching the flute, not you. Let it settle a while.": ["見ているのは笛で、あなたではない。しばらく落ち着かせよう。", "녀석이 보는 건 피리지 네가 아니다. 잠시 진정하게 둬라.", "它盯着的是笛子，不是你。让它缓一缓。", "牠盯著的是笛子，不是你。讓牠緩一緩。", "Nó đang nhìn cây sáo, không phải ngươi. Để nó yên một lúc.", "Ia memperhatikan serulingnya, bukan kamu. Biarkan ia tenang sebentar.", "มันจ้องขลุ่ย ไม่ใช่เจ้า ปล่อยให้มันสงบสักพัก", "Flütü izliyor, seni değil. Bir süre yatışsın.", "Mira la flauta, no a ti. Deja que se calme un rato.", "Ela observa a flauta, não você. Deixe-a se acalmar um pouco.", "Она смотрит на флейту, а не на вас. Дайте ей немного успокоиться.", "Вона дивиться на флейту, а не на вас. Дайте їй трохи заспокоїтися."],
  "It rises and sways to the tune, then sinks back, unsure. Play again in a while.": ["調べに合わせて鎌首をもたげて揺れるが、迷うように沈んでいく。しばらくしてまた吹こう。", "곡조에 맞춰 일어나 흔들리더니, 망설이듯 다시 가라앉는다. 잠시 후 다시 불어라.", "它随着曲调昂首摇摆，随后又犹豫着缩了回去。过一阵再吹吧。", "牠隨著曲調昂首搖擺，隨後又猶豫著縮了回去。過一陣再吹吧。", "Nó ngóc lên lắc lư theo điệu nhạc, rồi lại hạ xuống, còn ngập ngừng. Lát nữa thổi lại.", "Ia tegak dan bergoyang mengikuti nada, lalu turun lagi, ragu. Mainkan lagi sebentar lagi.", "มันชูคอโยกตามเพลง แล้วลดตัวลงอย่างลังเล เป่าใหม่อีกสักพัก", "Ezgiyle doğrulup salınıyor, sonra kararsızca geri çöküyor. Biraz sonra yine çal.", "Se alza y se mece con la melodía, y luego se recoge, dudosa. Vuelve a tocar dentro de un rato.", "Ela se ergue e balança com a melodia, depois recua, indecisa. Toque de novo daqui a pouco.", "Она поднимается и покачивается в такт, потом неуверенно опускается. Сыграйте снова чуть позже.", "Вона здіймається й погойдується в такт, потім невпевнено опускається. Зіграйте знову трохи згодом."],
  "There's an egg in the warm already.": ["もう卵がひとつ温まっている。", "이미 알 하나를 따뜻하게 하고 있다.", "已经有一枚蛋在保温了。", "已經有一枚蛋在保溫了。", "Đã có một quả trứng đang được ủ rồi.", "Sudah ada telur yang sedang dihangatkan.", "มีไข่กกอยู่ใบหนึ่งแล้ว", "Sıcakta zaten bir yumurta var.", "Ya hay un huevo al calor.", "Já há um ovo no calor.", "В тепле уже лежит одно яйцо.", "У теплі вже лежить одне яйце."],
  "You haven't a speckled drake egg. The drakes drop them, rarely.": ["まだら模様のドレイクの卵を持っていない。ドレイクがまれに落とす。", "얼룩무늬 드레이크 알이 없다. 드레이크가 드물게 떨어뜨린다.", "你没有斑点幼龙蛋。幼龙偶尔会掉落。", "你沒有斑點幼龍蛋。幼龍偶爾會掉落。", "Ngươi không có trứng rồng đốm. Rồng con hiếm khi đánh rơi.", "Kau tak punya telur drake berbintik. Para drake jarang menjatuhkannya.", "เจ้าไม่มีไข่เดรกลายจุด เดรกทำตกนานๆ ที", "Benekli bir ejderha yumurtan yok. Ejderha yavruları nadiren düşürür.", "No tienes ningún huevo de draco moteado. Los dracos los sueltan, rara vez.", "Você não tem um ovo de draco pintado. Os dracos deixam cair, raramente.", "У вас нет пятнистого яйца дрейка. Дрейки роняют их изредка.", "У вас немає плямистого яйця дрейка. Дрейки гублять їх зрідка."],
  "Keeping an egg warm that long costs {n} Frens.": ["それだけ長く卵を温めるには{n}フレンかかる。", "알을 그렇게 오래 따뜻하게 하려면 {n} 프렌이 든다.", "给蛋保温那么久要 {n} 友币。", "給蛋保溫那麼久要 {n} 友幣。", "Ủ ấm trứng lâu như vậy tốn {n} Fren.", "Menghangatkan telur selama itu seharga {n} Fren.", "การกกไข่นานขนาดนั้นใช้ {n} เฟรน", "Bir yumurtayı o kadar uzun sıcak tutmak {n} Fren tutar.", "Mantener un huevo caliente tanto tiempo cuesta {n} Frens.", "Manter um ovo quente por tanto tempo custa {n} Frens.", "Держать яйцо в тепле так долго стоит {n} френов.", "Тримати яйце в теплі так довго коштує {n} френів."],
  "The egg goes into the warm, among the coals. Come back in half an hour, and be the first thing it sees.": ["卵は炭火のあいだ、温かい所に置かれた。30分後に戻って、最初に目に入るものになろう。", "알이 숯불 사이 따뜻한 곳에 놓인다. 30분 뒤에 돌아와서, 알이 처음 보는 존재가 되어라.", "蛋被放进炭火间的暖处。半小时后回来，做它第一眼看到的东西。", "蛋被放進炭火間的暖處。半小時後回來，做牠第一眼看到的東西。", "Quả trứng được đặt vào chỗ ấm, giữa than hồng. Nửa giờ nữa quay lại, và hãy là thứ đầu tiên nó nhìn thấy.", "Telur itu ditaruh di tempat hangat, di antara bara. Kembalilah setengah jam lagi, dan jadilah yang pertama dilihatnya.", "ไข่ถูกวางไว้ในที่อุ่นท่ามกลางถ่าน กลับมาอีกครึ่งชั่วโมง แล้วเป็นสิ่งแรกที่มันเห็น", "Yumurta korların arasına, sıcağa konuyor. Yarım saat sonra gel ve gördüğü ilk şey ol.", "El huevo va al calor, entre las brasas. Vuelve dentro de media hora y sé lo primero que vea.", "O ovo vai para o calor, entre as brasas. Volte em meia hora e seja a primeira coisa que ele vê.", "Яйцо кладут в тепло, среди углей. Вернитесь через полчаса и будьте первым, кого оно увидит.", "Яйце кладуть у тепло, серед жару. Поверніться за пів години й будьте першим, кого воно побачить."],
  "Not yet. You'll hear it.": ["まだだ。そのときは音でわかる。", "아직이다. 때가 되면 들릴 거다.", "还没到时候。到时候你会听见的。", "還沒到時候。到時候你會聽見的。", "Chưa đâu. Ngươi sẽ nghe thấy.", "Belum. Kau akan mendengarnya.", "ยังหรอก เดี๋ยวเจ้าก็ได้ยินเอง", "Henüz değil. Duyacaksın.", "Todavía no. Ya lo oirás.", "Ainda não. Você vai ouvir.", "Ещё нет. Вы услышите.", "Ще ні. Ви почуєте."],
  "The shell splits, and a wet, furious drake looks straight at you. It's decided who its mother is.": ["殻が割れ、濡れて怒り狂ったドレイクがまっすぐあなたを見る。母親が誰か、もう決めたようだ。", "껍데기가 갈라지고, 젖은 채 화가 잔뜩 난 드레이크가 너를 똑바로 본다. 어미가 누군지 정했다.", "蛋壳裂开，一头湿漉漉、怒气冲冲的幼龙直直地看着你。它认定了谁是它的母亲。", "蛋殼裂開，一頭濕漉漉、怒氣沖沖的幼龍直直地看著你。牠認定了誰是牠的母親。", "Vỏ trứng nứt ra, một con rồng con ướt át, giận dữ nhìn thẳng vào ngươi. Nó đã chọn ai là mẹ.", "Cangkangnya retak, dan drake basah yang murka menatap lurus padamu. Ia sudah memutuskan siapa induknya.", "เปลือกแตกออก เดรกตัวเปียกที่โกรธจัดจ้องเจ้าเขม็ง มันตัดสินแล้วว่าใครคือแม่", "Kabuk yarılıyor ve ıslak, öfkeli bir ejderha yavrusu doğrudan sana bakıyor. Annesinin kim olduğuna karar verdi.", "La cáscara se parte y un draco mojado y furioso te mira fijamente. Ya ha decidido quién es su madre.", "A casca se parte e um draco molhado e furioso olha direto para você. Já decidiu quem é a mãe.", "Скорлупа трескается, и мокрый, разъярённый дрейк смотрит прямо на вас. Он решил, кто его мать.", "Шкаралупа тріскає, і мокрий, розлючений дрейк дивиться просто на вас. Він вирішив, хто його мати."],
  "Pip Featherstone the menagerist": ["動物園番のピップ・フェザーストーン", "동물원지기 핍 페더스톤", "动物园主皮普·费瑟斯通", "動物園主皮普·費瑟斯通", "Pip Featherstone người giữ thú", "Pip Featherstone si penjaga satwa", "พิพ เฟเธอร์สโตน ผู้ดูแลสวนสัตว์", "Hayvanat bekçisi Pip Featherstone", "Pip Featherstone la del zoológico", "Pip Featherstone, a do zoológico", "Пип Фезерстоун, смотрительница зверинца", "Піп Фезерстоун, доглядачка звіринця"],
  "Keeps Bellwhistle's menagerie: moths in jars, a pixie in a birdcage (it's let out on Thursdays), and a hen she swears is a wizard.": ["ベルホイッスルの動物園の番人。瓶詰めの蛾、鳥かごのピクシー（木曜日は出してもらえる）、そして魔法使いだと言い張る雌鶏。", "벨휘슬 동물원을 지킨다. 병 속의 나방, 새장 속의 픽시(목요일엔 풀려난다), 그리고 그녀가 마법사라고 우기는 암탉.", "看管铃哨镇的动物园：罐子里的飞蛾，鸟笼里的小精灵（每周四放出来），还有一只她发誓是巫师的母鸡。", "看管鈴哨鎮的動物園：罐子裡的飛蛾，鳥籠裡的小精靈（每週四放出來），還有一隻她發誓是巫師的母雞。", "Trông coi vườn thú của Bellwhistle: bướm đêm trong lọ, một tiên nhỏ trong lồng chim (được thả ra vào thứ Năm), và một con gà mái mà bà thề là phù thủy.", "Menjaga kebun satwa Bellwhistle: ngengat dalam toples, peri dalam sangkar burung (dilepas tiap Kamis), dan ayam betina yang ia sumpah adalah penyihir.", "ดูแลสวนสัตว์ของเบลล์วิสเซิล: ผีเสื้อกลางคืนในโถ พิกซี่ในกรงนก (ปล่อยออกมาวันพฤหัส) และแม่ไก่ที่นางสาบานว่าเป็นพ่อมด", "Bellwhistle'ın hayvanat bahçesine bakar: kavanozda güveler, kuş kafesinde bir peri (perşembeleri salınır) ve büyücü olduğuna yemin ettiği bir tavuk.", "Cuida del zoológico de Bellwhistle: polillas en tarros, un duendecillo en una jaula (lo sueltan los jueves) y una gallina que jura que es una maga.", "Cuida do zoológico de Bellwhistle: mariposas em potes, uma fadinha numa gaiola (solta às quintas) e uma galinha que ela jura ser uma maga.", "Смотрит за зверинцем Беллвисла: моль в банках, пикси в птичьей клетке (по четвергам выпускают) и курица, которая, клянётся она, волшебница.", "Доглядає звіринця Беллвісла: міль у банках, піксі в пташиній клітці (по четвергах випускають) і курка, яка, присягається вона, чарівниця."],
  "That hen is a wizard. Was. Is. She turned herself into a hen to get out of a faculty meeting, and liked it. Lays beautifully.": ["あの雌鶏は魔法使いよ。だった。今もそう。教授会をさぼるために自分を雌鶏に変えて、それが気に入っちゃったの。卵の産みっぷりも見事よ。", "저 암탉은 마법사야. 였지. 지금도 그렇고. 교수 회의를 빠지려고 자기를 암탉으로 바꿨는데, 마음에 들었나 봐. 알도 아주 잘 낳아.", "那只母鸡是个巫师。以前是。现在也是。她为了逃掉教务会议把自己变成了母鸡，结果还挺喜欢。蛋下得可漂亮了。", "那隻母雞是個巫師。以前是。現在也是。她為了逃掉教務會議把自己變成了母雞，結果還挺喜歡。蛋下得可漂亮了。", "Con gà mái đó là phù thủy. Đã từng. Vẫn là. Bà ấy tự biến thành gà để trốn họp khoa, rồi thích luôn. Đẻ trứng đẹp lắm.", "Ayam itu penyihir. Dulu. Masih. Ia mengubah dirinya jadi ayam supaya lolos dari rapat dewan guru, dan ternyata suka. Telurnya bagus sekali.", "แม่ไก่ตัวนั้นเป็นพ่อมด เคยเป็น ยังเป็นอยู่ นางแปลงตัวเป็นไก่เพื่อหนีประชุมคณะ แล้วก็ชอบซะงั้น ออกไข่สวยมาก", "O tavuk bir büyücü. İdi. Hâlâ öyle. Bir fakülte toplantısından kaçmak için kendini tavuğa çevirdi ve hoşuna gitti. Yumurtası da harikadır.", "Esa gallina es una maga. Lo era. Lo es. Se convirtió en gallina para librarse de una junta de facultad, y le gustó. Pone de maravilla.", "Aquela galinha é uma maga. Era. É. Virou galinha para fugir de uma reunião de professores e gostou. Bota lindamente.", "Эта курица — волшебница. Была. Есть. Превратилась в курицу, чтобы сбежать с заседания кафедры, и ей понравилось. Несётся чудесно.", "Ця курка — чарівниця. Була. Є. Перетворилася на курку, щоб утекти із засідання кафедри, і їй сподобалося. Несеться чудово."],
  "Wisps come to whoever can speak their light. Pixies come to whoever makes them laugh. Golems come to whoever knocks them over. Very simple creatures, golems.": ["ウィスプは光を語れる者のもとへ。ピクシーは笑わせてくれる者のもとへ。ゴーレムは自分を倒した者のもとへ。ゴーレムって単純なのよ。", "도깨비불은 제 빛을 말할 줄 아는 이에게 와. 픽시는 웃겨 주는 이에게 오고. 골렘은 자기를 쓰러뜨린 이에게 오지. 아주 단순한 녀석들이야, 골렘은.", "光灵会来找能说出它光芒之语的人。小精灵会来找逗它笑的人。魔像会来找把它撂倒的人。魔像啊，可是很单纯的生物。", "光靈會來找能說出牠光芒之語的人。小精靈會來找逗牠笑的人。魔像會來找把牠撂倒的人。魔像啊，可是很單純的生物。", "Ma trơi đến với ai biết nói ánh sáng của chúng. Tiên nhỏ đến với ai làm chúng cười. Người đá đến với ai quật ngã chúng. Người đá đơn giản lắm.", "Wisp datang pada siapa pun yang bisa mengucapkan cahayanya. Peri datang pada siapa pun yang membuatnya tertawa. Golem datang pada siapa pun yang merobohkannya. Makhluk yang sangat sederhana, golem itu.", "ภูตแสงมาหาผู้ที่พูดภาษาแสงของมันได้ พิกซี่มาหาผู้ที่ทำให้มันหัวเราะ โกเลมมาหาผู้ที่ล้มมันได้ โกเลมเป็นสิ่งมีชีวิตที่เรียบง่ายมาก", "Işıltılar ışıklarını konuşabilene gelir. Periler onları güldürene gelir. Golemler onları devirene gelir. Çok basit yaratıklardır golemler.", "Los fuegos fatuos acuden a quien sabe hablar su luz. Los duendecillos, a quien los hace reír. Los gólems, a quien los tumba. Criaturas muy simples, los gólems.", "Fogos-fátuos vêm a quem sabe falar a sua luz. Fadinhas vêm a quem as faz rir. Golems vêm a quem os derruba. Criaturas muito simples, os golems.", "Огоньки приходят к тому, кто умеет говорить на языке их света. Пикси — к тому, кто их смешит. Големы — к тому, кто их опрокинет. Очень простые существа эти големы.", "Вогники приходять до того, хто вміє говорити мовою їхнього світла. Піксі — до того, хто їх смішить. Големи — до того, хто їх перекине. Дуже прості створіння ці големи."],
  "Brush them! Nobody brushes them. Brush a moth and see what it does for you.": ["ブラシをかけてあげて！誰もやらないのよ。蛾にブラシをかけてごらん、どんなお返しがあるか。", "빗질해 줘! 아무도 안 해 준다니까. 나방을 빗질해 봐, 뭘 해 주는지 보라고.", "给它们刷刷毛！谁都不刷。给飞蛾刷一刷，看看它怎么报答你。", "給牠們刷刷毛！誰都不刷。給飛蛾刷一刷，看看牠怎麼報答你。", "Chải lông cho chúng đi! Chẳng ai chải cả. Chải cho một con bướm đêm rồi xem nó làm gì cho ngươi.", "Sikat mereka! Tak ada yang menyikat mereka. Sikat seekor ngengat dan lihat apa balasannya.", "แปรงขนให้พวกมันสิ! ไม่มีใครแปรงให้เลย ลองแปรงผีเสื้อกลางคืนดู แล้วดูว่ามันตอบแทนอะไร", "Tımar et onları! Kimse etmiyor. Bir güveyi tımar et de gör sana neler yapıyor.", "¡Cepíllalos! Nadie los cepilla. Cepilla a una polilla y verás lo que hace por ti.", "Escove-os! Ninguém escova. Escove uma mariposa e veja o que ela faz por você.", "Чистите их! Никто их не чистит. Почистите моль и увидите, что она для вас сделает.", "Чистіть їх! Ніхто їх не чистить. Почистіть міль і побачите, що вона для вас зробить."],
  "{x} is untrained.": ["{x}はまだ訓練していない。", "{x}은(는) 훈련받지 않았다.", "{x}还没受过训练。", "{x}還沒受過訓練。", "{x} chưa được huấn luyện.", "{x} belum terlatih.", "{x}ยังไม่ได้ฝึก", "{x} eğitimsiz.", "{x} no está adiestrado.", "{x} não está treinado.", "{x} не обучен.", "{x} не навчений."],
  "I set it; you do it.": ["課題は私が出す。やるのはあなた。", "과제는 내가 내고, 해내는 건 너다.", "我来布置，你来完成。", "我來佈置，你來完成。", "Ta đặt bài; ngươi làm.", "Aku yang menetapkan; kau yang menjalankan.", "ข้าตั้งโจทย์ เจ้าเป็นคนทำ", "Ben belirlerim; sen yaparsın.", "Yo lo pongo; tú lo haces.", "Eu passo; você faz.", "Я задаю, вы делаете.", "Я задаю, ви робите."],
  "{x} has learnt everything anyone can teach it. It could teach me a thing or two.": ["{x}は教えられることをすべて覚えた。私が教わりたいくらいよ。", "{x}은(는) 가르칠 수 있는 건 다 배웠다. 오히려 내가 배워야겠다.", "{x}把能教的都学会了。倒是能反过来教我两招。", "{x}把能教的都學會了。倒是能反過來教我兩招。", "{x} đã học mọi thứ ai có thể dạy. Nó có thể dạy ta vài điều đấy.", "{x} sudah mempelajari semua yang bisa diajarkan. Ia bahkan bisa mengajariku satu-dua hal.", "{x}เรียนรู้ทุกอย่างที่ใครจะสอนได้แล้ว มันสอนข้ากลับได้ด้วยซ้ำ", "{x} öğretilebilecek her şeyi öğrendi. Bana bir iki şey öğretebilir.", "{x} ha aprendido todo lo que se le puede enseñar. Podría enseñarme un par de cosas.", "{x} aprendeu tudo o que se pode ensinar. Poderia me ensinar uma ou duas coisas.", "{x} выучил всё, чему его можно научить. Ещё меня поучит.", "{x} вивчив усе, чого його можна навчити. Ще мене повчить."],
  "Set it its training.": ["訓練を課す。", "훈련을 맡긴다.", "给它布置训练。", "給牠佈置訓練。", "Giao bài huấn luyện cho nó.", "Tetapkan pelatihannya.", "ตั้งการฝึกให้มัน", "Eğitimini belirle.", "Ponle su adiestramiento.", "Passe o treinamento.", "Задать ему обучение.", "Задати йому навчання."],
  "It's moving. It's cracking. Quick, be the first thing it sees!": ["動いてる。割れてきた。早く、最初に見るものになって！", "움직여. 금이 가고 있어. 얼른, 처음 보는 존재가 돼!", "它在动。裂开了。快，做它第一眼看到的东西！", "牠在動。裂開了。快，做牠第一眼看到的東西！", "Nó đang động đậy. Nó đang nứt. Nhanh, hãy là thứ đầu tiên nó thấy!", "Ia bergerak. Ia retak. Cepat, jadilah yang pertama dilihatnya!", "มันขยับแล้ว มันกำลังแตก เร็วเข้า เป็นสิ่งแรกที่มันเห็นสิ!", "Kıpırdıyor. Çatlıyor. Çabuk, gördüğü ilk şey ol!", "Se mueve. Se está rompiendo. ¡Rápido, sé lo primero que vea!", "Está se mexendo. Está rachando. Rápido, seja a primeira coisa que ele vê!", "Шевелится. Трескается. Скорее, будьте первым, кого оно увидит!", "Ворушиться. Тріскає. Швидше, будьте першим, кого воно побачить!"],
  "I'm here.": ["ここにいる。", "나 여기 있어.", "我在这儿。", "我在這兒。", "Ta ở đây.", "Aku di sini.", "ข้าอยู่นี่", "Buradayım.", "Aquí estoy.", "Estou aqui.", "Я здесь.", "Я тут."],
  "Still warm, still ticking. Come back in a while. You'll want to be here when it goes.": ["まだ温かくて、まだコツコツ鳴ってる。しばらくしたら戻ってきて。孵るときはここにいたいでしょう。", "아직 따뜻하고, 아직 똑딱거려. 잠시 후에 다시 와. 깰 때는 여기 있고 싶을 테니까.", "还热着，还在嘀嗒响。过一阵再来。破壳的时候你肯定想在场。", "還熱著，還在嘀嗒響。過一陣再來。破殼的時候你肯定想在場。", "Vẫn còn ấm, vẫn còn tích tắc. Lát nữa quay lại. Ngươi sẽ muốn có mặt khi nó nở.", "Masih hangat, masih berdetak. Kembalilah nanti. Kau pasti ingin ada di sini saat ia menetas.", "ยังอุ่น ยังมีเสียงติ๊กๆ อยู่ กลับมาอีกสักพัก ตอนมันฟักเจ้าคงอยากอยู่ตรงนี้", "Hâlâ sıcak, hâlâ tıkırdıyor. Biraz sonra gel. Çatladığında burada olmak istersin.", "Sigue caliente, sigue haciendo tictac. Vuelve dentro de un rato. Querrás estar aquí cuando se abra.", "Ainda quente, ainda tiquetaqueando. Volte daqui a pouco. Você vai querer estar aqui quando chocar.", "Ещё тёплое, ещё тикает. Загляните попозже. Вы захотите быть здесь, когда оно треснет.", "Ще тепле, ще цокає. Загляньте пізніше. Ви захочете бути тут, коли воно трісне."],
  "Here's the egg.": ["卵はこれよ。", "여기 알이야.", "蛋在这儿。", "蛋在這兒。", "Trứng đây.", "Ini telurnya.", "นี่ไข่", "İşte yumurta.", "Aquí está el huevo.", "Aqui está o ovo.", "Вот яйцо.", "Ось яйце."],
  "Its training.": ["訓練のこと。", "훈련 이야기.", "它的训练。", "牠的訓練。", "Việc huấn luyện nó.", "Pelatihannya.", "การฝึกของมัน", "Eğitimi.", "Su adiestramiento.", "O treinamento dele.", "Его обучение.", "Його навчання."],
  "A drake egg.": ["ドレイクの卵。", "드레이크 알.", "幼龙蛋。", "幼龍蛋。", "Trứng rồng.", "Telur drake.", "ไข่เดรก", "Ejderha yumurtası.", "Un huevo de draco.", "Um ovo de draco.", "Яйцо дрейка.", "Яйце дрейка."],
  "Creatures won one way each and kept beside you: fed until they trust you, rescued, spared, haltered, earned. One out at a time, the rest kept by the beastkeepers (Bramble on the Friendhollow farm, Halla in Skarnholm, Mstislav in Krasnogor, Pip in Bellwhistle). Trained by bonding, by caring for them, and by what they do beside you.": ["それぞれ違うやり方で手に入れ、そばに置く生き物たち。信頼するまで餌をやり、助け、見逃し、端綱をかけ、勝ち取る。連れ出せるのは一度に一匹、残りは獣使いが預かる（フレンドホロウ農場のブランブル、スカーンホルムのハラ、クラスノゴルのムスティスラフ、ベルホイッスルのピップ）。絆を結び、世話をし、共に働くことで鍛えられる。", "저마다 다른 방법으로 얻어 곁에 두는 생물들. 믿을 때까지 먹이고, 구하고, 살려 주고, 고삐를 씌우고, 얻어 낸다. 한 번에 하나만 데리고 나가고, 나머지는 조련사들이 맡는다 (프렌드할로 농장의 브램블, 스카른홀름의 할라, 크라스노고르의 므스티슬라프, 벨휘슬의 핍). 유대를 맺고, 돌보고, 곁에서 함께하는 일로 훈련된다.", "每种生物都有各自的收服方法，收服后留在你身边：喂到它信任你、救下它、饶过它、套上笼头、赢得它。一次只能带一只出门，其余的由驯兽人照看（友谷农场的布兰波、斯卡恩霍尔姆的哈拉、克拉斯诺戈尔的姆斯季斯拉夫、铃哨镇的皮普）。靠结下羁绊、悉心照料和并肩作战来训练。", "每種生物都有各自的收服方法，收服後留在你身邊：餵到牠信任你、救下牠、饒過牠、套上籠頭、贏得牠。一次只能帶一隻出門，其餘的由馴獸人照看（友谷農場的布蘭波、斯卡恩霍爾姆的哈拉、克拉斯諾戈爾的姆斯季斯拉夫、鈴哨鎮的皮普）。靠結下羈絆、悉心照料和並肩作戰來訓練。", "Những sinh vật mỗi loài một cách thu phục rồi giữ bên mình: cho ăn đến khi tin ngươi, giải cứu, tha mạng, tròng dây dắt, giành lấy. Mỗi lần dẫn một con, số còn lại do người nuôi thú giữ (Bramble ở trang trại Friendhollow, Halla ở Skarnholm, Mstislav ở Krasnogor, Pip ở Bellwhistle). Rèn luyện bằng gắn bó, chăm sóc, và những gì chúng làm bên ngươi.", "Makhluk yang masing-masing didapat dengan caranya sendiri dan dipelihara di sisimu: diberi makan sampai percaya, diselamatkan, diampuni, dikekang, diraih. Satu dibawa keluar sekali waktu, sisanya dijaga para penjinak (Bramble di peternakan Friendhollow, Halla di Skarnholm, Mstislav di Krasnogor, Pip di Bellwhistle). Dilatih lewat ikatan, perawatan, dan apa yang mereka lakukan di sisimu.", "สิ่งมีชีวิตที่ได้มาด้วยวิธีของแต่ละชนิดและอยู่ข้างเจ้า: ป้อนอาหารจนไว้ใจ ช่วยชีวิต ไว้ชีวิต สวมบังเหียน หรือได้มาด้วยความดีความชอบ พาออกได้ทีละตัว ที่เหลือผู้เลี้ยงสัตว์ดูแลไว้ (แบรมเบิลที่ฟาร์มเฟรนด์ฮอลโลว์ ฮัลลาที่สการ์นโฮล์ม มสติสลาฟที่คราสโนกอร์ พิพที่เบลล์วิสเซิล) ฝึกด้วยความผูกพัน การดูแล และสิ่งที่พวกมันทำข้างเจ้า", "Her biri kendi yoluyla kazanılıp yanında tutulan yaratıklar: güvenene dek beslenen, kurtarılan, bağışlanan, yular takılan, hak edilen. Bir seferde biri dışarıda, gerisi bakıcılarda (Friendhollow çiftliğinde Bramble, Skarnholm'da Halla, Krasnogor'da Mstislav, Bellwhistle'da Pip). Bağ kurarak, onlara bakarak ve yanında yaptıklarıyla gelişir.", "Criaturas que se ganan cada una a su manera y que te acompañan: alimentadas hasta que confían, rescatadas, perdonadas, enronzaladas, merecidas. Una fuera a la vez; el resto lo guardan los cuidadores de bestias (Bramble en la granja de Friendhollow, Halla en Skarnholm, Mstislav en Krasnogor, Pip en Bellwhistle). Se entrena creando vínculos, cuidándolas y con lo que hacen a tu lado.", "Criaturas conquistadas cada uma do seu jeito e mantidas ao seu lado: alimentadas até confiarem, resgatadas, poupadas, encabrestadas, merecidas. Uma fora de cada vez; as demais ficam com os tratadores (Bramble na fazenda de Friendhollow, Halla em Skarnholm, Mstislav em Krasnogor, Pip em Bellwhistle). Treina-se criando laços, cuidando delas e pelo que fazem ao seu lado.", "Существа, которых каждое добывают по-своему и держат при себе: кормят, пока не доверятся, спасают, щадят, надевают недоуздок, заслуживают. Выводить можно по одному, остальных держат звероводы (Брамбл на ферме Френдхоллоу, Халла в Скарнхольме, Мстислав в Красногоре, Пип в Беллвисле). Навык растёт от уз, заботы и того, что звери делают рядом с вами.", "Створіння, яких кожне здобувають по-своєму й тримають при собі: годують, доки не довіряться, рятують, милують, надягають недоуздок, заслуговують. Виводити можна по одному, решту тримають звірівники (Брамбл на фермі Френдголлоу, Халла в Скарнгольмі, Мстислав у Красногорі, Піп у Беллвіслі). Навичка зростає від зв'язку, турботи й того, що звірі роблять поруч із вами."],
  "Grooming": ["ブラッシング", "빗질", "梳毛", "梳毛", "Chải lông", "Merawat bulu", "การแปรงขน", "Tımar", "Cepillado", "Escovação", "Уход", "Догляд"],
  "Use a grooming brush on your companion now and then: it deepens the bond, it's worth Beastkeeping XP, and it counts toward its training.": ["ときどき相棒にグルーミングブラシを使おう。絆が深まり、獣使いの経験値になり、訓練の務めにも数えられる。", "이따금 동료에게 손질 빗을 써라. 유대가 깊어지고, 조련술 경험치가 되며, 훈련에도 들어간다.", "时不时给伙伴用梳毛刷：能加深羁绊，能获得驯兽经验，还算作训练的一件事。", "時不時給夥伴用梳毛刷：能加深羈絆，能獲得馴獸經驗，還算作訓練的一件事。", "Thỉnh thoảng dùng bàn chải lông cho bạn đồng hành: nó làm sâu đậm gắn bó, cho XP Thuần thú, và tính vào việc huấn luyện.", "Sesekali gunakan sikat bulu pada pendampingmu: mempererat ikatan, memberi XP Penjinakan, dan terhitung dalam pelatihannya.", "ใช้แปรงขนกับคู่หูเป็นครั้งคราว: เพิ่มความผูกพัน ได้ค่าประสบการณ์การเลี้ยงสัตว์ และนับเป็นภารกิจการฝึก", "Arada bir yoldaşına tımar fırçası kullan: bağı derinleştirir, Hayvan bakıcılığı XP'si kazandırır ve eğitimine sayılır.", "Usa de vez en cuando un cepillo de aseo con tu compañero: estrecha el vínculo, da XP de Doma de bestias y cuenta para su adiestramiento.", "Use de vez em quando uma escova de pelos no seu companheiro: aprofunda o laço, dá XP de Doma de feras e conta para o treinamento.", "Время от времени чистите спутника щёткой: это крепит узы, даёт опыт Звероводства и засчитывается в обучение.", "Час від часу чистіть супутника щіткою: це зміцнює зв'язок, дає досвід Звірівництва й зараховується в навчання."],
  "Produce": ["収穫", "산물", "产出", "產出", "Sản vật", "Hasil", "ผลผลิต", "Ürün", "Productos", "Produtos", "Добыча", "Здобуток"],
  "A hen, a sheep, a milk cow, a silk spider, a glimmer moth, a jewelled peafowl or a tomb beetle brings you something while it's out with you: eggs, wool, milk (carry a bucket), silk, glimmer dust, feathers, gold scarabs.": ["雌鶏、羊、乳牛、絹蜘蛛、きらめき蛾、宝石クジャク、墓守甲虫は、連れ歩いているあいだ何かを持ってくる：卵、羊毛、牛乳（バケツを持とう）、絹、きらめきの粉、羽根、金のスカラベ。", "암탉, 양, 젖소, 비단거미, 반짝나방, 보석공작, 무덤딱정벌레는 데리고 다니는 동안 뭔가를 가져온다: 달걀, 양털, 우유(양동이를 들고 다녀라), 비단, 반짝이 가루, 깃털, 황금 풍뎅이.", "母鸡、羊、奶牛、丝蛛、微光蛾、宝石孔雀或墓穴甲虫跟着你时会带来东西：蛋、羊毛、牛奶（带上桶）、丝绸、微光粉尘、羽毛、金圣甲虫。", "母雞、羊、乳牛、絲蛛、微光蛾、寶石孔雀或墓穴甲蟲跟著你時會帶來東西：蛋、羊毛、牛奶（帶上桶）、絲綢、微光粉塵、羽毛、金聖甲蟲。", "Gà mái, cừu, bò sữa, nhện tơ, bướm đêm lấp lánh, công châu báu hay bọ lăng mộ sẽ mang đến thứ gì đó khi đi cùng ngươi: trứng, lông cừu, sữa (mang theo xô), lụa, bụi lấp lánh, lông vũ, bọ hung vàng.", "Ayam betina, domba, sapi perah, laba-laba sutra, ngengat kilau, merak permata, atau kumbang makam membawakanmu sesuatu saat ikut denganmu: telur, wol, susu (bawa ember), sutra, debu kilau, bulu, kumbang skarab emas.", "แม่ไก่ แกะ วัวนม แมงมุมไหม ผีเสื้อกลางคืนประกาย นกยูงอัญมณี หรือด้วงสุสาน จะนำของมาให้ระหว่างที่อยู่กับเจ้า: ไข่ ขนแกะ นม (พกถัง) ไหม ผงประกาย ขนนก แมลงสคารับทองคำ", "Bir tavuk, koyun, süt ineği, ipek örümceği, pırıltı güvesi, mücevherli tavus kuşu ya da mezar böceği yanındayken sana bir şeyler getirir: yumurta, yün, süt (kova taşı), ipek, pırıltı tozu, tüy, altın bokböceği.", "Una gallina, una oveja, una vaca lechera, una araña de seda, una polilla de destello, un pavo real enjoyado o un escarabajo de tumba te traen algo mientras te acompañan: huevos, lana, leche (lleva un cubo), seda, polvo de destello, plumas, escarabajos de oro.", "Uma galinha, uma ovelha, uma vaca leiteira, uma aranha-da-seda, uma mariposa cintilante, um pavão cravejado ou um besouro-de-tumba trazem algo enquanto andam com você: ovos, lã, leite (leve um balde), seda, pó cintilante, penas, escaravelhos de ouro.", "Курица, овца, дойная корова, шелковый паук, мерцающая моль, самоцветный павлин или гробничный жук, пока они с вами, что-нибудь приносят: яйца, шерсть, молоко (носите ведро), шёлк, мерцающую пыльцу, перья, золотых скарабеев.", "Курка, вівця, дійна корова, шовковий павук, мерехтлива міль, самоцвітний павич чи гробничний жук, поки вони з вами, щось приносять: яйця, вовну, молоко (носіть відро), шовк, мерехтливий пилок, пір'я, золотих скарабеїв."],
  "Training: {x}": ["訓練：{x}", "훈련: {x}", "训练：{x}", "訓練：{x}", "Huấn luyện: {x}", "Pelatihan: {x}", "การฝึก: {x}", "Eğitim: {x}", "Adiestramiento: {x}", "Treinamento: {x}", "Обучение: {x}", "Навчання: {x}"],
  "The Keeper's Trial": ["獣使いの試練", "조련사의 시험", "驯兽人的试炼", "馴獸人的試煉", "Thử thách người nuôi thú", "Ujian Sang Penjinak", "บททดสอบผู้เลี้ยงสัตว์", "Bakıcının Sınavı", "La Prueba del Cuidador", "A Prova do Tratador", "Испытание зверовода", "Випробування звірівника"],
  "Bramble's challenge: your fighting companion brings down creatures against the clock, for Beastkeeping XP, a deeper bond and a deed toward its training.": ["ブランブルの挑戦：戦う相棒が時間内に生き物を倒す。報酬は獣使いの経験値、深まる絆、訓練の務め一回分。", "브램블의 도전: 싸우는 동료가 제한 시간 안에 생물을 쓰러뜨린다. 보상은 조련술 경험치, 깊어진 유대, 훈련 한 번.", "布兰波的挑战：你那会战斗的伙伴要在限时内撂倒生物，可得驯兽经验、更深的羁绊，以及一件训练的事。", "布蘭波的挑戰：你那會戰鬥的夥伴要在限時內撂倒生物，可得馴獸經驗、更深的羈絆，以及一件訓練的事。", "Thử thách của Bramble: bạn đồng hành chiến đấu của ngươi hạ sinh vật trong thời gian giới hạn, đổi lấy XP Thuần thú, gắn bó sâu hơn và một việc huấn luyện.", "Tantangan Bramble: pendamping petarungmu merobohkan makhluk melawan waktu, demi XP Penjinakan, ikatan lebih erat, dan satu perbuatan untuk pelatihannya.", "ความท้าทายของแบรมเบิล: คู่หูนักสู้ของเจ้าล้มสิ่งมีชีวิตแข่งกับเวลา แลกกับค่าประสบการณ์การเลี้ยงสัตว์ ความผูกพันที่ลึกขึ้น และหนึ่งภารกิจการฝึก", "Bramble'ın sınavı: dövüşen yoldaşın zamana karşı yaratıkları devirir; karşılığında Hayvan bakıcılığı XP'si, derinleşen bir bağ ve eğitimine bir iş.", "El reto de Bramble: tu compañero luchador abate criaturas contra el reloj, a cambio de XP de Doma de bestias, un vínculo más hondo y una hazaña para su adiestramiento.", "O desafio de Bramble: seu companheiro lutador derruba criaturas contra o relógio, em troca de XP de Doma de feras, um laço mais fundo e um feito para o treinamento.", "Вызов Брамбл: ваш боевой спутник валит существ на время — за опыт Звероводства, более крепкие узы и одно дело в счёт обучения.", "Виклик Брамбл: ваш бойовий супутник валить створінь на час — за досвід Звірівництва, міцніший зв'язок і одну справу в рахунок навчання."],
  "Another companion": ["もう一匹の相棒", "동료 하나 더", "再多一个伙伴", "再多一個夥伴", "Thêm một bạn đồng hành", "Satu pendamping lagi", "คู่หูอีกตัว", "Bir yoldaş daha", "Otro compañero", "Mais um companheiro", "Ещё один спутник", "Ще один супутник"],
  "You can keep {n} companions now.": ["今は相棒を{n}匹まで連れていられる。", "이제 동료를 {n}마리까지 둘 수 있다.", "现在你最多能养 {n} 个伙伴。", "現在你最多能養 {n} 個夥伴。", "Giờ ngươi có thể giữ {n} bạn đồng hành.", "Kini kau bisa memelihara {n} pendamping.", "ตอนนี้เจ้าเลี้ยงคู่หูได้ {n} ตัว", "Artık {n} yoldaş tutabilirsin.", "Ahora puedes tener {n} compañeros.", "Agora você pode ter {n} companheiros.", "Теперь можно держать {n} спутников.", "Тепер можна тримати {n} супутників."],
  "A speckled drake egg": ["まだら模様のドレイクの卵", "얼룩무늬 드레이크 알", "斑点幼龙蛋", "斑點幼龍蛋", "Trứng rồng đốm", "Telur drake berbintik", "ไข่เดรกลายจุด", "Benekli ejderha yumurtası", "Un huevo de draco moteado", "Um ovo de draco pintado", "Пятнистое яйцо дрейка", "Плямисте яйце дрейка"],
  "The drakes drop an egg, rarely. A beastkeeper keeps it warm for {n} Frens; be there when it hatches, and the drake is yours.": ["ドレイクはまれに卵を落とす。獣使いが{n}フレンで温めてくれる。孵るときにそこにいれば、ドレイクはあなたのもの。", "드레이크는 드물게 알을 떨어뜨린다. 조련사가 {n} 프렌에 따뜻하게 해 준다. 알이 깰 때 곁에 있으면 드레이크는 네 것이다.", "幼龙偶尔会掉下一枚蛋。驯兽人收 {n} 友币替你保温；破壳时你在场，幼龙就归你了。", "幼龍偶爾會掉下一枚蛋。馴獸人收 {n} 友幣替你保溫；破殼時你在場，幼龍就歸你了。", "Rồng con hiếm khi đánh rơi một quả trứng. Người nuôi thú ủ ấm nó với giá {n} Fren; có mặt khi nó nở, và rồng con là của ngươi.", "Para drake jarang menjatuhkan telur. Penjinak menghangatkannya seharga {n} Fren; hadirlah saat menetas, dan drake itu milikmu.", "เดรกทำไข่ตกนานๆ ที ผู้เลี้ยงสัตว์กกให้ในราคา {n} เฟรน อยู่ตรงนั้นตอนมันฟัก แล้วเดรกจะเป็นของเจ้า", "Ejderha yavruları nadiren yumurta düşürür. Bir bakıcı onu {n} Fren karşılığında sıcak tutar; çatladığında orada ol, ejderha senin olur.", "Los dracos sueltan un huevo, rara vez. Un cuidador de bestias lo mantiene caliente por {n} Frens; estate allí cuando eclosione y el draco será tuyo.", "Os dracos deixam cair um ovo, raramente. Um tratador o mantém quente por {n} Frens; esteja lá quando chocar e o draco será seu.", "Дрейки изредка роняют яйцо. Зверовод держит его в тепле за {n} френов; будьте рядом, когда оно треснет, и дрейк ваш.", "Дрейки зрідка гублять яйце. Звірівник тримає його в теплі за {n} френів; будьте поруч, коли воно трісне, і дрейк ваш."],
  "Bring a companion that fights, out with you. I'm trying it, not you.": ["戦える相棒を連れてきな。試すのはあの子で、あんたじゃない。", "싸울 줄 아는 동료를 데리고 와. 시험받는 건 그 녀석이지, 네가 아니야.", "把会打架的伙伴带出来。我考的是它，不是你。", "把會打架的夥伴帶出來。我考的是牠，不是你。", "Dẫn theo một bạn đồng hành biết chiến đấu. Ta thử nó, không phải ngươi.", "Bawa pendamping yang bisa bertarung. Yang kuuji dia, bukan kau.", "พาคู่หูที่สู้เป็นออกมาด้วย ข้าทดสอบมัน ไม่ใช่เจ้า", "Dövüşen bir yoldaşı yanında getir. Sınadığım o, sen değil.", "Trae contigo a un compañero que luche. Lo pongo a prueba a él, no a ti.", "Traga um companheiro que lute. Quem eu testo é ele, não você.", "Приведите спутника, который дерётся. Испытываю я его, а не вас.", "Приведіть супутника, який б'ється. Випробовую я його, а не вас."],
  "Out you go with your companion, and it brings down {n} creatures inside a quarter of an hour: its own blow the last one each time. I'll know by the look of it when you come back.": ["相棒と出かけて、15分以内に生き物を{n}匹倒させな。毎回とどめはあの子の一撃でね。戻ってきたら顔つきでわかるよ。", "동료와 나가서, 15분 안에 생물 {n}마리를 쓰러뜨리게 해. 매번 마지막 일격은 그 녀석 몫이어야 해. 돌아오면 눈빛만 봐도 알아.", "带上伙伴出去，一刻钟内让它撂倒 {n} 只生物：每一只的最后一击都得是它自己的。你回来时我看它的样子就知道。", "帶上夥伴出去，一刻鐘內讓牠撂倒 {n} 隻生物：每一隻的最後一擊都得是牠自己的。你回來時我看牠的樣子就知道。", "Đi ra ngoài cùng bạn đồng hành, và để nó hạ {n} sinh vật trong vòng mười lăm phút: mỗi lần, đòn cuối phải là của nó. Ngươi quay lại là ta nhìn mặt nó biết ngay.", "Keluarlah bersama pendampingmu, dan biar ia merobohkan {n} makhluk dalam seperempat jam: pukulan terakhir harus darinya setiap kali. Aku akan tahu dari raut wajahnya saat kau kembali.", "ออกไปกับคู่หู แล้วให้มันล้มสิ่งมีชีวิต {n} ตัวภายในสิบห้านาที: ทุกครั้งต้องเป็นมันที่ปิดฉาก เจ้ากลับมาเมื่อไหร่ ข้าดูหน้ามันก็รู้", "Yoldaşınla çık ve çeyrek saat içinde {n} yaratık devirsin: her seferinde son darbe onun olsun. Döndüğünde halinden anlarım.", "Sal con tu compañero y que abata {n} criaturas en un cuarto de hora: el último golpe, cada vez, el suyo. Lo sabré por su cara cuando volváis.", "Saia com seu companheiro e faça-o derrubar {n} criaturas em quinze minutos: o golpe final, toda vez, dele. Vou saber pela cara dele quando voltarem.", "Отправляйтесь со спутником, и пусть он за четверть часа свалит {n} существ: последний удар каждый раз за ним. Когда вернётесь, я пойму по его виду.", "Вирушайте із супутником, і хай він за чверть години звалить {n} створінь: останній удар щоразу за ним. Коли повернетеся, я зрозумію з його вигляду."],
  "{n} Beastkeeping XP and a deeper bond": ["獣使い経験値{n}と深まった絆", "조련술 경험치 {n}과 깊어진 유대", "{n} 驯兽经验和更深的羁绊", "{n} 馴獸經驗和更深的羈絆", "{n} XP Thuần thú và gắn bó sâu hơn", "{n} XP Penjinakan dan ikatan yang lebih erat", "ค่าประสบการณ์การเลี้ยงสัตว์ {n} และความผูกพันที่ลึกขึ้น", "{n} Hayvan bakıcılığı XP'si ve derinleşen bir bağ", "{n} XP de Doma de bestias y un vínculo más hondo", "{n} XP de Doma de feras e um laço mais fundo", "{n} опыта Звероводства и более крепкие узы", "{n} досвіду Звірівництва й міцніший зв'язок"],
  "Beastkeeping XP, a deeper bond, and a deed toward its training.": ["獣使いの経験値、深まる絆、それに訓練の務め一回分。", "조련술 경험치, 깊어진 유대, 그리고 훈련 한 번.", "驯兽经验、更深的羁绊，外加一件训练的事。", "馴獸經驗、更深的羈絆，外加一件訓練的事。", "XP Thuần thú, gắn bó sâu hơn, và một việc huấn luyện.", "XP Penjinakan, ikatan lebih erat, dan satu perbuatan untuk pelatihannya.", "ค่าประสบการณ์การเลี้ยงสัตว์ ความผูกพันที่ลึกขึ้น และหนึ่งภารกิจการฝึก", "Hayvan bakıcılığı XP'si, derinleşen bir bağ ve eğitimine bir iş.", "XP de Doma de bestias, un vínculo más hondo y una hazaña para su adiestramiento.", "XP de Doma de feras, um laço mais fundo e um feito para o treinamento.", "Опыт Звероводства, более крепкие узы и одно дело в счёт обучения.", "Досвід Звірівництва, міцніший зв'язок і одна справа в рахунок навчання."],
  "Halter": ["端綱", "고삐", "笼头", "籠頭", "Dây dắt", "Tali kekang", "บังเหียน", "Yular", "Ronzal", "Cabresto", "Недоуздок", "Недоуздок"],
  "Rope and leather, for a sheep or a milk cow (or a goat, at a pinch). Use it on one: Beastkeeping 5 for a sheep, 8 for a cow.": ["縄と革でできた、羊か乳牛用（いざとなればヤギにも）。使うには獣使い：羊は5、牛は8。", "밧줄과 가죽으로 만든 것으로, 양이나 젖소용 (급하면 염소에게도). 쓰려면 조련술: 양은 5, 소는 8.", "绳子和皮革做的，给羊或奶牛用（实在不行山羊也行）。对它使用：羊需驯兽 5，牛需 8。", "繩子和皮革做的，給羊或乳牛用（實在不行山羊也行）。對牠使用：羊需馴獸 5，牛需 8。", "Dây thừng và da, dành cho cừu hoặc bò sữa (dê cũng được, nếu cần). Dùng lên một con: Thuần thú 5 với cừu, 8 với bò.", "Tali dan kulit, untuk domba atau sapi perah (atau kambing, kalau terpaksa). Pakai pada salah satunya: Penjinakan 5 untuk domba, 8 untuk sapi.", "เชือกกับหนัง สำหรับแกะหรือวัวนม (หรือแพะ ถ้าจำเป็น) ใช้กับตัวหนึ่ง: การเลี้ยงสัตว์ 5 สำหรับแกะ 8 สำหรับวัว", "Halat ve deri; bir koyun ya da süt ineği için (sıkışırsan keçi için de). Birine kullan: koyun için Hayvan bakıcılığı 5, inek için 8.", "Cuerda y cuero, para una oveja o una vaca lechera (o una cabra, si no hay otra). Úsalo con una: Doma de bestias 5 para una oveja, 8 para una vaca.", "Corda e couro, para uma ovelha ou uma vaca leiteira (ou uma cabra, se preciso). Use numa delas: Doma de feras 5 para ovelha, 8 para vaca.", "Верёвка и кожа, для овцы или дойной коровы (на худой конец — козы). Используйте на животном: Звероводство 5 для овцы, 8 для коровы.", "Мотузка й шкіра, для вівці чи дійної корови (на крайній випадок — кози). Використайте на тварині: Звірівництво 5 для вівці, 8 для корови."],
  "Grooming brush": ["グルーミングブラシ", "손질 빗", "梳毛刷", "梳毛刷", "Bàn chải lông", "Sikat bulu", "แปรงขน", "Tımar fırçası", "Cepillo de aseo", "Escova de pelos", "Щётка для ухода", "Щітка для догляду"],
  "Stiff bristles on a beech back. Use it on your companion now and then: it likes it, and it trusts you the more.": ["ブナの柄に硬い毛。ときどき相棒に使おう：喜ぶし、もっと信頼してくれる。", "너도밤나무 등판에 뻣뻣한 털. 이따금 동료에게 써라: 좋아하고, 너를 더 믿게 된다.", "山毛榉刷背上插着硬鬃毛。时不时给伙伴用一用：它喜欢，也会更信任你。", "山毛櫸刷背上插著硬鬃毛。時不時給夥伴用一用：牠喜歡，也會更信任你。", "Lông cứng trên đế gỗ sồi. Thỉnh thoảng dùng cho bạn đồng hành: nó thích, và tin ngươi hơn.", "Bulu kaku di gagang kayu beech. Sesekali pakai pada pendampingmu: ia suka, dan makin percaya padamu.", "ขนแข็งบนหลังไม้บีช ใช้กับคู่หูเป็นครั้งคราว: มันชอบ และไว้ใจเจ้ามากขึ้น", "Kayın sırtlı, sert kıllı. Arada bir yoldaşına kullan: hoşuna gider ve sana daha çok güvenir.", "Cerdas duras sobre un dorso de haya. Úsalo de vez en cuando con tu compañero: le gusta y confía más en ti.", "Cerdas duras num dorso de faia. Use de vez em quando no seu companheiro: ele gosta e confia mais em você.", "Жёсткая щетина на буковой колодке. Время от времени чистите ею спутника: ему нравится, и он больше вам доверяет.", "Жорстка щетина на буковій колодці. Час від часу чистіть нею супутника: йому подобається, і він більше вам довіряє."],
  "Charmer's flute": ["蛇使いの笛", "뱀 부리는 피리", "弄蛇人的笛子", "弄蛇人的笛子", "Sáo dụ rắn", "Seruling pawang ular", "ขลุ่ยหมองู", "Yılan oynatıcısı flütü", "Flauta de encantador", "Flauta de encantador", "Флейта заклинателя", "Флейта заклинача"],
  "A reed flute with a gourd at its foot. Play it to a hooded serpent: Beastkeeping 48. It isn't used up.": ["根元にひょうたんのついた葦笛。フードコブラに吹いて聞かせよう：獣使い48。なくならない。", "끝에 박이 달린 갈대 피리. 두건뱀에게 불어 줘라: 조련술 48. 닳지 않는다.", "一支底部接着葫芦的芦笛。吹给眼镜蛇听：驯兽 48。不会消耗。", "一支底部接著葫蘆的蘆笛。吹給眼鏡蛇聽：馴獸 48。不會消耗。", "Một cây sáo sậy có quả bầu ở đuôi. Thổi cho rắn hổ mang nghe: Thuần thú 48. Không bị hao mòn.", "Seruling buluh dengan labu di ujungnya. Mainkan untuk ular kobra: Penjinakan 48. Tidak habis terpakai.", "ขลุ่ยอ้อที่มีน้ำเต้าตรงปลาย เป่าให้งูเห่าฟัง: การเลี้ยงสัตว์ 48 ใช้ได้ไม่หมด", "Ucunda su kabağı olan bir kamış flüt. Bir kukuletalı yılana çal: Hayvan bakıcılığı 48. Tükenmez.", "Una flauta de caña con una calabaza al pie. Tócala ante una serpiente de capucha: Doma de bestias 48. No se gasta.", "Uma flauta de junco com uma cabaça na ponta. Toque para uma serpente-de-capuz: Doma de feras 48. Não se gasta.", "Тростниковая флейта с тыквой у основания. Сыграйте капюшонной змее: Звероводство 48. Не расходуется.", "Очеретяна флейта з гарбузом біля основи. Зіграйте каптуровій змії: Звірівництво 48. Не витрачається."],
  "Speckled drake egg": ["まだら模様のドレイクの卵", "얼룩무늬 드레이크 알", "斑点幼龙蛋", "斑點幼龍蛋", "Trứng rồng đốm", "Telur drake berbintik", "ไข่เดรกลายจุด", "Benekli ejderha yumurtası", "Huevo de draco moteado", "Ovo de draco pintado", "Пятнистое яйцо дрейка", "Плямисте яйце дрейка"],
  "A drake's egg from the wild, speckled and heavy and warm as a hearth. A beastkeeper could keep it warm until it hatches: Beastkeeping 88.": ["野生のドレイクの卵。まだら模様で重く、炉のように温かい。獣使いなら孵るまで温めてくれる：獣使い88。", "야생 드레이크의 알. 얼룩덜룩하고 무거우며 화로처럼 따뜻하다. 조련사라면 깰 때까지 따뜻하게 해 줄 수 있다: 조련술 88.", "一枚野生幼龙的蛋，带斑点，沉甸甸的，像炉膛一样温热。驯兽人能替你保温到它破壳：驯兽 88。", "一枚野生幼龍的蛋，帶斑點，沉甸甸的，像爐膛一樣溫熱。馴獸人能替你保溫到牠破殼：馴獸 88。", "Một quả trứng rồng hoang, lốm đốm, nặng trịch và ấm như bếp lò. Người nuôi thú có thể ủ ấm cho đến khi nở: Thuần thú 88.", "Telur drake liar, berbintik, berat, dan hangat bagai perapian. Penjinak bisa menghangatkannya sampai menetas: Penjinakan 88.", "ไข่เดรกป่า ลายจุด หนัก และอุ่นเหมือนเตาผิง ผู้เลี้ยงสัตว์กกให้จนฟักได้: การเลี้ยงสัตว์ 88", "Yabanıl bir ejderha yumurtası; benekli, ağır ve ocak gibi sıcak. Bir bakıcı çatlayana dek sıcak tutabilir: Hayvan bakıcılığı 88.", "Un huevo de draco salvaje, moteado, pesado y caliente como un hogar. Un cuidador de bestias podría mantenerlo caliente hasta que eclosione: Doma de bestias 88.", "Um ovo de draco selvagem, pintado, pesado e quente como uma lareira. Um tratador poderia mantê-lo quente até chocar: Doma de feras 88.", "Яйцо дикого дрейка, пятнистое, тяжёлое и тёплое, как очаг. Зверовод может держать его в тепле, пока не вылупится: Звероводство 88.", "Яйце дикого дрейка, плямисте, важке й тепле, як вогнище. Звірівник може тримати його в теплі, доки не вилупиться: Звірівництво 88."],
  "Pip's Menagerie": ["ピップの動物園", "핍의 동물원", "皮普的动物园", "皮普的動物園", "Vườn thú của Pip", "Kebun Satwa Pip", "สวนสัตว์ของพิพ", "Pip'in Hayvanat Bahçesi", "La Casa de Fieras de Pip", "O Zoológico de Pip", "Зверинец Пип", "Звіринець Піп"],
  "Pip's trough, for whatever's thirsty": ["喉の渇いた何にでも使えるピップの水桶", "목마른 누구든 마시라고 둔 핍의 여물통", "皮普的水槽，谁渴了都能喝", "皮普的水槽，誰渴了都能喝", "Máng nước của Pip, cho bất cứ thứ gì đang khát", "Palung Pip, untuk apa saja yang haus", "รางน้ำของพิพ สำหรับตัวไหนก็ตามที่กระหาย", "Pip'in yalağı, susayan ne varsa onun için", "El abrevadero de Pip, para lo que tenga sed", "O cocho de Pip, para o que tiver sede", "Корыто Пип, для всякого, кто хочет пить", "Корито Піп, для всякого, хто хоче пити"],
  "A hutch with something purple in it": ["何か紫色のものが入った小屋", "뭔가 보라색이 들어 있는 우리", "一个关着什么紫色东西的笼舍", "一個關著什麼紫色東西的籠舍", "Một cái chuồng có thứ gì đó màu tím bên trong", "Kandang berisi sesuatu yang ungu", "กรงที่มีอะไรสีม่วงอยู่ข้างใน", "İçinde mor bir şey olan bir kafes", "Una conejera con algo morado dentro", "Uma gaiola com algo roxo dentro", "Клетка, а в ней что-то фиолетовое", "Клітка, а в ній щось фіолетове"],
  "Beastkeeping, grown": ["大きくなった獣使い", "커진 조련술", "驯兽，长大了", "馴獸，長大了", "Thuần thú, lớn mạnh", "Penjinakan, tumbuh besar", "การเลี้ยงสัตว์ เติบโตขึ้น", "Hayvan bakıcılığı büyüdü", "La Doma de bestias, crecida", "A Doma de feras cresceu", "Звероводство подросло", "Звірівництво підросло"],
  "Fourteen new companions: a hen, a sheep and a milk cow, a silk spider, a glimmer moth, a jewelled peafowl, a marsh adder, a thistle pixie, a prism wisp, a tomb beetle, a hooded serpent, a glimmer stag, a shard golem and a drake.": ["新しい相棒が14種：雌鶏、羊と乳牛、絹蜘蛛、きらめき蛾、宝石クジャク、沼マムシ、アザミのピクシー、プリズムウィスプ、墓守甲虫、フードコブラ、きらめき鹿、欠片のゴーレム、そしてドレイク。", "새 동료 14종: 암탉, 양과 젖소, 비단거미, 반짝나방, 보석공작, 늪독사, 엉겅퀴 픽시, 프리즘 도깨비불, 무덤딱정벌레, 두건뱀, 반짝사슴, 파편 골렘, 그리고 드레이크.", "十四种新伙伴：母鸡、羊和奶牛、丝蛛、微光蛾、宝石孔雀、沼泽蝰蛇、蓟草小精灵、棱光光灵、墓穴甲虫、眼镜蛇、微光雄鹿、碎晶魔像，还有幼龙。", "十四種新夥伴：母雞、羊和乳牛、絲蛛、微光蛾、寶石孔雀、沼澤蝰蛇、薊草小精靈、稜光光靈、墓穴甲蟲、眼鏡蛇、微光雄鹿、碎晶魔像，還有幼龍。", "Mười bốn bạn đồng hành mới: gà mái, cừu và bò sữa, nhện tơ, bướm đêm lấp lánh, công châu báu, rắn đầm lầy, tiên gai, ma trơi lăng kính, bọ lăng mộ, rắn hổ mang, hươu lấp lánh, người đá mảnh vỡ và rồng con.", "Empat belas pendamping baru: ayam betina, domba dan sapi perah, laba-laba sutra, ngengat kilau, merak permata, ular rawa, peri onak, wisp prisma, kumbang makam, ular kobra, rusa kilau, golem serpihan, dan drake.", "คู่หูใหม่สิบสี่ชนิด: แม่ไก่ แกะและวัวนม แมงมุมไหม ผีเสื้อกลางคืนประกาย นกยูงอัญมณี งูพิษหนองน้ำ พิกซี่หนาม ภูตแสงปริซึม ด้วงสุสาน งูเห่า กวางประกาย โกเลมเศษผลึก และเดรก", "On dört yeni yoldaş: bir tavuk, bir koyun ve bir süt ineği, bir ipek örümceği, bir pırıltı güvesi, mücevherli bir tavus kuşu, bir bataklık engereği, bir deve dikeni perisi, bir prizma ışıltısı, bir mezar böceği, bir kukuletalı yılan, bir pırıltı geyiği, bir kırık golemi ve bir ejderha yavrusu.", "Catorce compañeros nuevos: una gallina, una oveja y una vaca lechera, una araña de seda, una polilla de destello, un pavo real enjoyado, una víbora de pantano, un duendecillo de cardo, un fuego fatuo prismático, un escarabajo de tumba, una serpiente de capucha, un ciervo de destello, un gólem de esquirlas y un draco.", "Catorze companheiros novos: uma galinha, uma ovelha e uma vaca leiteira, uma aranha-da-seda, uma mariposa cintilante, um pavão cravejado, uma víbora do pântano, uma fadinha-do-cardo, um fogo-fátuo prismático, um besouro-de-tumba, uma serpente-de-capuz, um cervo cintilante, um golem de estilhaços e um draco.", "Четырнадцать новых спутников: курица, овца и дойная корова, шелковый паук, мерцающая моль, самоцветный павлин, болотная гадюка, чертополоховый пикси, призменный огонёк, гробничный жук, капюшонная змея, мерцающий олень, осколочный голем и дрейк.", "Чотирнадцять нових супутників: курка, вівця й дійна корова, шовковий павук, мерехтлива міль, самоцвітний павич, болотяна гадюка, будяковий піксі, призмовий вогник, гробничний жук, каптурова змія, мерехтливий олень, уламковий голем і дрейк."],
  "Produce: a hen lays eggs while she's out with you, a sheep gives wool, a cow milk (carry a bucket), a spider silk, a moth glimmer dust, a peafowl jewelled feathers, a tomb beetle gold scarabs.": ["収穫：雌鶏は連れ歩くあいだ卵を産み、羊は羊毛、牛は牛乳（バケツを持とう）、蜘蛛は絹、蛾はきらめきの粉、クジャクは宝石の羽根、墓守甲虫は金のスカラベをくれる。", "산물: 암탉은 데리고 다니는 동안 알을 낳고, 양은 양털을, 소는 우유를(양동이를 들고 다녀라), 거미는 비단을, 나방은 반짝이 가루를, 공작은 보석 깃털을, 무덤딱정벌레는 황금 풍뎅이를 준다.", "产出：母鸡跟着你时会下蛋，羊给羊毛，牛给牛奶（带上桶），蜘蛛给丝绸，飞蛾给微光粉尘，孔雀给宝石羽毛，墓穴甲虫给金圣甲虫。", "產出：母雞跟著你時會下蛋，羊給羊毛，牛給牛奶（帶上桶），蜘蛛給絲綢，飛蛾給微光粉塵，孔雀給寶石羽毛，墓穴甲蟲給金聖甲蟲。", "Sản vật: gà mái đẻ trứng khi đi cùng ngươi, cừu cho lông, bò cho sữa (mang theo xô), nhện cho lụa, bướm đêm cho bụi lấp lánh, công cho lông vũ châu báu, bọ lăng mộ cho bọ hung vàng.", "Hasil: ayam betina bertelur saat ikut denganmu, domba memberi wol, sapi susu (bawa ember), laba-laba sutra, ngengat debu kilau, merak bulu permata, kumbang makam kumbang skarab emas.", "ผลผลิต: แม่ไก่ออกไข่ระหว่างอยู่กับเจ้า แกะให้ขน วัวให้นม (พกถัง) แมงมุมให้ไหม ผีเสื้อกลางคืนให้ผงประกาย นกยูงให้ขนอัญมณี ด้วงสุสานให้แมลงสคารับทองคำ", "Ürün: tavuk yanındayken yumurtlar, koyun yün verir, inek süt (kova taşı), örümcek ipek, güve pırıltı tozu, tavus kuşu mücevherli tüy, mezar böceği altın bokböceği.", "Productos: una gallina pone huevos mientras te acompaña, una oveja da lana, una vaca leche (lleva un cubo), una araña seda, una polilla polvo de destello, un pavo real plumas enjoyadas, un escarabajo de tumba escarabajos de oro.", "Produtos: uma galinha bota ovos enquanto anda com você, uma ovelha dá lã, uma vaca leite (leve um balde), uma aranha seda, uma mariposa pó cintilante, um pavão penas cravejadas, um besouro-de-tumba escaravelhos de ouro.", "Добыча: курица, пока она с вами, несёт яйца, овца даёт шерсть, корова — молоко (носите ведро), паук — шёлк, моль — мерцающую пыльцу, павлин — самоцветные перья, гробничный жук — золотых скарабеев.", "Здобуток: курка, поки вона з вами, несе яйця, вівця дає вовну, корова — молоко (носіть відро), павук — шовк, міль — мерехтливий пилок, павич — самоцвітне пір'я, гробничний жук — золотих скарабеїв."],
  "Knacks: every fighter has its own now. A salamander's bite burns, a bear mauls, an adder or a serpent poisons, a pixie throws sparks, a golem draws the blows meant for you, and a drake breathes fire on what you fight and whatever's beside it.": ["得意技：戦う相棒それぞれに技ができた。サラマンダーの噛みつきは焼け付き、熊は叩きのめし、マムシやコブラは毒を回し、ピクシーは火花を投げ、ゴーレムはあなたへの攻撃を引き受け、ドレイクは敵とその隣のものに炎を吐く。", "특기: 싸우는 동료마다 저만의 특기가 생겼다. 도롱뇽의 물기는 불타고, 곰은 할퀴고, 독사나 코브라는 독을 퍼뜨리고, 픽시는 불꽃을 던지고, 골렘은 너에게 올 공격을 대신 받고, 드레이크는 적과 그 옆의 것에 불을 뿜는다.", "绝活：每个会战斗的伙伴现在都有自己的本事。火蜥蜴的咬伤会灼烧，熊会猛拍，蝰蛇或眼镜蛇会下毒，小精灵会扔火花，魔像会替你挨打，幼龙会朝你的对手和它身边的东西喷火。", "絕活：每個會戰鬥的夥伴現在都有自己的本事。火蜥蜴的咬傷會灼燒，熊會猛拍，蝰蛇或眼鏡蛇會下毒，小精靈會扔火花，魔像會替你挨打，幼龍會朝你的對手和牠身邊的東西噴火。", "Sở trường: mỗi bạn chiến đấu giờ đều có tài riêng. Vết cắn của kỳ giông bỏng rát, gấu vồ nát, rắn đầm lầy hay rắn hổ mang gây độc, tiên nhỏ ném tia lửa, người đá đỡ đòn thay ngươi, và rồng con phun lửa vào kẻ ngươi đánh lẫn thứ đứng cạnh nó.", "Keahlian: setiap petarung kini punya kemampuannya sendiri. Gigitan salamander membakar, beruang mencakar habis, ular berbisa atau kobra meracuni, peri melempar percikan, golem menarik serangan yang ditujukan padamu, dan drake menyemburkan api ke musuhmu dan apa pun di sebelahnya.", "ทักษะเฉพาะ: นักสู้ทุกตัวมีทักษะของตัวเองแล้ว รอยกัดของซาลาแมนเดอร์แผดเผา หมีตะปบ งูพิษหรืองูเห่าทำให้ติดพิษ พิกซี่ขว้างประกายไฟ โกเลมรับการโจมตีแทนเจ้า และเดรกพ่นไฟใส่ศัตรูกับทุกสิ่งที่อยู่ข้างๆ", "Marifetler: artık her dövüşçünün kendine has bir marifeti var. Semenderin ısırığı yakar, ayı hırpalar, engerek ya da kobra zehirler, peri kıvılcım atar, golem sana gelen darbeleri üstüne çeker, ejderha yavrusu da dövüştüğün şeye ve yanındakine ateş püskürür.", "Mañas: ahora cada luchador tiene la suya. La mordedura de una salamandra quema, un oso destroza, una víbora o una serpiente envenenan, un duendecillo lanza chispas, un gólem se lleva los golpes dirigidos a ti y un draco escupe fuego sobre lo que combates y lo que tenga al lado.", "Talentos: agora cada lutador tem o seu. A mordida de uma salamandra queima, um urso estraçalha, uma víbora ou uma serpente envenenam, uma fadinha atira faíscas, um golem atrai os golpes destinados a você e um draco cospe fogo no que você enfrenta e no que estiver ao lado.", "Умения: теперь у каждого бойца своё. Укус саламандры обжигает, медведь мнёт, гадюка или змея отравляют, пикси мечет искры, голем принимает удары, предназначенные вам, а дрейк дышит огнём на ваших врагов и на всё, что рядом.", "Уміння: тепер у кожного бійця своє. Укус саламандри обпікає, ведмідь мне, гадюка чи змія отруюють, піксі жбурляє іскри, голем бере на себе удари, призначені вам, а дрейк дихає вогнем на ваших ворогів і на все, що поруч."],
  "Training: a beastkeeper sets a companion its training (Beastkeeping 15, 30, 50, 70 and 90), and you do it together out there. Each tier makes it stronger, quicker to bring things in and easier on the road.": ["訓練：獣使いが相棒の訓練を課し（獣使い15、30、50、70、90）、あなたが外で一緒にこなす。段階が上がるたびに強くなり、収穫が早まり、旅が楽になる。", "훈련: 조련사가 동료의 훈련을 정해 주고(조련술 15, 30, 50, 70, 90), 너는 밖에서 함께 해낸다. 단계마다 더 강해지고, 더 빨리 가져오고, 길이 편해진다.", "训练：驯兽人为伙伴布置训练（驯兽 15、30、50、70 和 90），你们在外头一起完成。每升一阶它就更强、带回东西更快、赶路更轻松。", "訓練：馴獸人為夥伴佈置訓練（馴獸 15、30、50、70 和 90），你們在外頭一起完成。每升一階牠就更強、帶回東西更快、趕路更輕鬆。", "Huấn luyện: người nuôi thú đặt bài cho bạn đồng hành (Thuần thú 15, 30, 50, 70 và 90), và ngươi cùng nó làm ngoài kia. Mỗi bậc khiến nó mạnh hơn, mang đồ về nhanh hơn và đường đi nhẹ nhàng hơn.", "Pelatihan: penjinak menetapkan pelatihan pendamping (Penjinakan 15, 30, 50, 70 dan 90), dan kalian menjalaninya bersama di luar sana. Tiap tingkat membuatnya lebih kuat, lebih cepat membawa hasil, dan jalan lebih ringan.", "การฝึก: ผู้เลี้ยงสัตว์ตั้งการฝึกให้คู่หู (การเลี้ยงสัตว์ 15, 30, 50, 70 และ 90) แล้วเจ้าทำด้วยกันข้างนอก แต่ละขั้นทำให้มันแข็งแกร่งขึ้น นำของมาเร็วขึ้น และเดินทางง่ายขึ้น", "Eğitim: bir bakıcı yoldaşına eğitim belirler (Hayvan bakıcılığı 15, 30, 50, 70 ve 90), siz de dışarıda birlikte yaparsınız. Her kademe onu daha güçlü, daha çabuk getiren ve yolda daha rahat yapar.", "Adiestramiento: un cuidador de bestias le pone a tu compañero su adiestramiento (Doma de bestias 15, 30, 50, 70 y 90) y lo hacéis juntos ahí fuera. Cada grado lo hace más fuerte, más rápido en traer cosas y más llevadero en el camino.", "Treinamento: um tratador passa o treinamento do seu companheiro (Doma de feras 15, 30, 50, 70 e 90) e vocês fazem juntos lá fora. Cada nível o deixa mais forte, mais rápido para trazer coisas e mais leve na estrada.", "Обучение: зверовод задаёт спутнику обучение (Звероводство 15, 30, 50, 70 и 90), а вы проходите его вместе там, снаружи. Каждая ступень делает его сильнее, быстрее в добыче и легче в пути.", "Навчання: звірівник задає супутникові навчання (Звірівництво 15, 30, 50, 70 і 90), а ви проходите його разом там, назовні. Кожен щабель робить його сильнішим, швидшим у здобутку й легшим у дорозі."],
  "Grooming brushes, halters for sheep and cows, a charmer's flute for the serpents, and the speckled drake egg: the drakes drop one, rarely, and a beastkeeper hatches it. Be there when it does.": ["グルーミングブラシ、羊と牛の端綱、コブラ用の蛇使いの笛、そしてまだら模様のドレイクの卵：ドレイクがまれに落とし、獣使いが孵してくれる。そのときはその場にいよう。", "손질 빗, 양과 소의 고삐, 코브라를 위한 뱀 부리는 피리, 그리고 얼룩무늬 드레이크 알: 드레이크가 드물게 떨어뜨리고, 조련사가 부화시켜 준다. 그때 곁에 있어라.", "梳毛刷、羊和牛的笼头、对付眼镜蛇的弄蛇人笛子，还有斑点幼龙蛋：幼龙偶尔掉落，驯兽人负责孵化。孵出来时你得在场。", "梳毛刷、羊和牛的籠頭、對付眼鏡蛇的弄蛇人笛子，還有斑點幼龍蛋：幼龍偶爾掉落，馴獸人負責孵化。孵出來時你得在場。", "Bàn chải lông, dây dắt cho cừu và bò, sáo dụ rắn cho rắn hổ mang, và trứng rồng đốm: rồng con hiếm khi đánh rơi, người nuôi thú ấp nở. Hãy có mặt khi nó nở.", "Sikat bulu, tali kekang untuk domba dan sapi, seruling pawang untuk ular kobra, dan telur drake berbintik: para drake jarang menjatuhkannya, dan penjinak menetaskannya. Hadirlah saat itu.", "แปรงขน บังเหียนสำหรับแกะและวัว ขลุ่ยหมองูสำหรับงูเห่า และไข่เดรกลายจุด: เดรกทำตกนานๆ ที แล้วผู้เลี้ยงสัตว์ฟักให้ อยู่ตรงนั้นตอนมันฟักด้วย", "Tımar fırçaları, koyun ve inekler için yularlar, kobralar için yılan oynatıcısı flütü ve benekli ejderha yumurtası: ejderha yavruları nadiren düşürür, bir bakıcı çatlatır. O an orada ol.", "Cepillos de aseo, ronzales para ovejas y vacas, una flauta de encantador para las serpientes y el huevo de draco moteado: los dracos lo sueltan, rara vez, y un cuidador de bestias lo empolla. Estate allí cuando eclosione.", "Escovas de pelos, cabrestos para ovelhas e vacas, uma flauta de encantador para as serpentes e o ovo de draco pintado: os dracos o deixam cair, raramente, e um tratador o choca. Esteja lá quando chocar.", "Щётки для ухода, недоуздки для овец и коров, флейта заклинателя для змей и пятнистое яйцо дрейка: дрейки изредка его роняют, а зверовод выводит. Будьте рядом, когда это случится.", "Щітки для догляду, недоуздки для овець і корів, флейта заклинача для змій і плямисте яйце дрейка: дрейки зрідка його гублять, а звірівник виводить. Будьте поруч, коли це станеться."],
  "Keep more: one more companion at Beastkeeping 25, 50 and 75, six in all. A wisp lights the dark underground. A glimmer stag eases the road more than a stag does.": ["もっと連れていける：獣使い25、50、75で一匹ずつ増え、全部で6匹。ウィスプは地下の暗闇を照らす。きらめき鹿は普通の鹿よりも旅を楽にしてくれる。", "더 많이: 조련술 25, 50, 75에 동료가 하나씩 늘어 모두 여섯. 도깨비불은 어두운 지하를 밝힌다. 반짝사슴은 보통 사슴보다 길을 더 편하게 해 준다.", "养得更多：驯兽 25、50、75 时各多一个，最多六个。光灵能照亮黑暗的地下。微光雄鹿比普通雄鹿更能让你赶路轻松。", "養得更多：馴獸 25、50、75 時各多一個，最多六個。光靈能照亮黑暗的地下。微光雄鹿比普通雄鹿更能讓你趕路輕鬆。", "Giữ được nhiều hơn: thêm một bạn đồng hành ở Thuần thú 25, 50 và 75, tổng cộng sáu. Ma trơi soi sáng lòng đất tối tăm. Hươu lấp lánh giúp đường đi nhẹ hơn cả hươu thường.", "Pelihara lebih banyak: satu pendamping lagi di Penjinakan 25, 50, dan 75, enam semuanya. Wisp menerangi gelapnya bawah tanah. Rusa kilau meringankan perjalanan lebih dari rusa biasa.", "เลี้ยงได้มากขึ้น: เพิ่มคู่หูอีกตัวที่การเลี้ยงสัตว์ 25, 50 และ 75 รวมหกตัว ภูตแสงส่องความมืดใต้ดิน กวางประกายทำให้เดินทางง่ายกว่ากวางธรรมดา", "Daha fazla tut: Hayvan bakıcılığı 25, 50 ve 75'te birer yoldaş daha, toplam altı. Işıltı karanlık yeraltını aydınlatır. Pırıltı geyiği yolu bir geyikten de fazla kolaylaştırır.", "Más compañeros: uno más con Doma de bestias 25, 50 y 75, seis en total. Un fuego fatuo alumbra la oscuridad bajo tierra. Un ciervo de destello aligera el camino más que un ciervo.", "Mais companheiros: mais um com Doma de feras 25, 50 e 75, seis ao todo. Um fogo-fátuo ilumina a escuridão subterrânea. Um cervo cintilante alivia a estrada mais do que um cervo.", "Больше спутников: ещё по одному на Звероводстве 25, 50 и 75, всего шесть. Огонёк освещает тьму подземелий. Мерцающий олень облегчает дорогу сильнее, чем обычный.", "Більше супутників: ще по одному на Звірівництві 25, 50 і 75, загалом шість. Вогник освітлює темряву підземель. Мерехтливий олень полегшує дорогу більше, ніж звичайний."],
  "The Keeper's Trial: Bramble's challenge for you and your companion. And Pip Featherstone has opened a menagerie in Bellwhistle.": ["獣使いの試練：あなたと相棒へのブランブルの挑戦。それに、ピップ・フェザーストーンがベルホイッスルに動物園を開いた。", "조련사의 시험: 너와 동료를 위한 브램블의 도전. 그리고 핍 페더스톤이 벨휘슬에 동물원을 열었다.", "驯兽人的试炼：布兰波给你和伙伴的挑战。还有，皮普·费瑟斯通在铃哨镇开了家动物园。", "馴獸人的試煉：布蘭波給你和夥伴的挑戰。還有，皮普·費瑟斯通在鈴哨鎮開了家動物園。", "Thử thách người nuôi thú: thử thách của Bramble cho ngươi và bạn đồng hành. Và Pip Featherstone đã mở một vườn thú ở Bellwhistle.", "Ujian Sang Penjinak: tantangan Bramble untukmu dan pendampingmu. Dan Pip Featherstone telah membuka kebun satwa di Bellwhistle.", "บททดสอบผู้เลี้ยงสัตว์: ความท้าทายของแบรมเบิลสำหรับเจ้าและคู่หู และพิพ เฟเธอร์สโตนเปิดสวนสัตว์ในเบลล์วิสเซิลแล้ว", "Bakıcının Sınavı: Bramble'ın sana ve yoldaşına meydan okuması. Ayrıca Pip Featherstone Bellwhistle'da bir hayvanat bahçesi açtı.", "La Prueba del Cuidador: el reto de Bramble para ti y tu compañero. Y Pip Featherstone ha abierto una casa de fieras en Bellwhistle.", "A Prova do Tratador: o desafio de Bramble para você e seu companheiro. E Pip Featherstone abriu um zoológico em Bellwhistle.", "Испытание зверовода: вызов Брамбл вам и вашему спутнику. А Пип Фезерстоун открыла зверинец в Беллвисле.", "Випробування звірівника: виклик Брамбл вам і вашому супутникові. А Піп Фезерстоун відкрила звіринець у Беллвіслі."],
  "{x} could give you more, if you'd something to put it in ({item}).": ["入れ物（{item}）さえあれば、{x}はもっとくれるのに。", "담을 것({item})만 있으면 {x}이(가) 더 줄 텐데.", "要是你有东西装（{item}），{x}还能给你更多。", "要是你有東西裝（{item}），{x}還能給你更多。", "{x} có thể cho ngươi thêm, nếu ngươi có thứ để đựng ({item}).", "{x} bisa memberimu lebih, kalau kau punya wadahnya ({item}).", "{x}ให้เจ้าได้อีก ถ้าเจ้ามีอะไรใส่ ({item})", "Koyacak bir şeyin ({item}) olsaydı {x} sana daha fazlasını verirdi.", "{x} podría darte más, si tuvieras dónde ponerlo ({item}).", "{x} poderia dar mais, se você tivesse onde pôr ({item}).", "{x} мог бы дать больше, будь у вас во что положить ({item}).", "{x} міг би дати більше, якби у вас було куди покласти ({item})."],
  "{x} has learnt all you were teaching it: {tier} now.": ["{x}は教えたことをすべて身につけた。今や{tier}だ。", "{x}이(가) 네가 가르친 것을 모두 익혔다. 이제 {tier}이다.", "{x}学会了你教的一切：现在是{tier}了。", "{x}學會了你教的一切：現在是{tier}了。", "{x} đã học hết những gì ngươi dạy: giờ đã {tier}.", "{x} telah mempelajari semua yang kau ajarkan: kini {tier}.", "{x}เรียนรู้ทุกอย่างที่เจ้าสอนแล้ว ตอนนี้{tier}", "{x} öğrettiğin her şeyi öğrendi: artık {tier}.", "{x} ha aprendido todo lo que le enseñabas: ahora está {tier}.", "{x} aprendeu tudo o que você ensinava: agora está {tier}.", "{x} усвоил всё, чему вы учили: теперь он {tier}.", "{x} засвоїв усе, чого ви навчали: тепер він {tier}."],
  "{x}'s training so far: {tier}.": ["{x}の訓練の段階：{tier}。", "{x}의 지금까지 훈련: {tier}.", "{x}目前的训练：{tier}。", "{x}目前的訓練：{tier}。", "Mức huấn luyện của {x} đến giờ: {tier}.", "Pelatihan {x} sejauh ini: {tier}.", "การฝึกของ{x}ตอนนี้: {tier}", "{x} eğitiminde şu an: {tier}.", "Adiestramiento de {x} hasta ahora: {tier}.", "Treinamento de {x} até agora: {tier}.", "Обучение {x} на сей день: {tier}.", "Навчання {x} наразі: {tier}."],
  "Next it'd be {x}: Beastkeeping {n}, {n2} Frens for my time, and {n3} deeds done together out there.": ["次は{x}。獣使い{n}、私の手間賃に{n2}フレン、それに外で一緒に{n3}回の務め。", "다음은 {x}이다. 조련술 {n}, 내 수고비로 {n2} 프렌, 그리고 밖에서 함께 해낼 일 {n3}번.", "下一步是{x}：驯兽 {n}，我的辛苦费 {n2} 友币，再加上在外头一起完成 {n3} 件事。", "下一步是{x}：馴獸 {n}，我的辛苦費 {n2} 友幣，再加上在外頭一起完成 {n3} 件事。", "Tiếp theo sẽ là {x}: Thuần thú {n}, {n2} Fren tiền công của ta, và {n3} việc cùng nhau làm ngoài kia.", "Berikutnya {x}: Penjinakan {n}, {n2} Fren untuk jerih payahku, dan {n3} perbuatan bersama di luar sana.", "ขั้นต่อไปคือ{x}: การเลี้ยงสัตว์ {n} ค่าแรงข้า {n2} เฟรน และภารกิจ {n3} อย่างที่ทำด้วยกันข้างนอก", "Sırada {x} var: Hayvan bakıcılığı {n}, emeğim için {n2} Fren ve dışarıda birlikte {n3} iş.", "Lo siguiente sería {x}: Doma de bestias {n}, {n2} Frens por mi tiempo y {n3} hazañas juntos ahí fuera.", "O próximo seria {x}: Doma de feras {n}, {n2} Frens pelo meu tempo e {n3} feitos juntos lá fora.", "Дальше — {x}: Звероводство {n}, {n2} френов за мои труды и {n3} дел, сделанных сообща там, снаружи.", "Далі — {x}: Звірівництво {n}, {n2} френів за мої труди й {n3} справ, зроблених спільно там, назовні."],
  "{x} is {n} of {n2} deeds into its training. Keep working with it: fights won together, what it brings in, brushing it down, the road.": ["{x}の訓練は{n}／{n2}回の務めまで進んでいる。一緒に続けよう：共に勝つ戦い、持ってくる収穫、ブラッシング、旅路。", "{x}의 훈련은 {n}/{n2}번째 일까지 왔다. 계속 함께해라: 같이 이긴 싸움, 가져오는 것, 빗질, 길.", "{x}的训练已完成 {n}/{n2} 件事。继续和它一起努力：一起打赢的仗、它带回的东西、给它刷毛、一起赶路。", "{x}的訓練已完成 {n}/{n2} 件事。繼續和牠一起努力：一起打贏的仗、牠帶回的東西、給牠刷毛、一起趕路。", "{x} đã làm được {n} trên {n2} việc trong khóa huấn luyện. Tiếp tục cùng nó: thắng trận cùng nhau, thứ nó mang về, chải lông, đường đi.", "{x} sudah {n} dari {n2} perbuatan dalam pelatihannya. Terus bekerja bersamanya: pertarungan dimenangkan bersama, hasil yang dibawanya, menyikatnya, perjalanan.", "{x}ฝึกไปแล้ว {n} จาก {n2} ภารกิจ ทำต่อไปด้วยกัน: ชนะการต่อสู้ด้วยกัน ของที่มันนำมา แปรงขน การเดินทาง", "{x} eğitiminde {n}/{n2} işte. Onunla çalışmaya devam et: birlikte kazanılan dövüşler, getirdikleri, tımar, yol.", "{x} lleva {n} de {n2} hazañas de su adiestramiento. Sigue trabajando con él: combates ganados juntos, lo que trae, cepillarlo, el camino.", "{x} está em {n} de {n2} feitos do treinamento. Continue trabalhando com ele: lutas vencidas juntos, o que ele traz, escová-lo, a estrada.", "{x} прошёл {n} из {n2} дел своего обучения. Продолжайте вместе: бои, выигранные сообща, то, что он приносит, чистка, дорога.", "{x} пройшов {n} з {n2} справ свого навчання. Працюйте далі разом: бої, виграні спільно, те, що він приносить, чищення, дорога."],
  "A speckled drake egg? Bring me one and {n} Frens for the coal, and I'll keep it warm half an hour. Be here when it hatches: whoever it sees first is its mother. Beastkeeping {n2}, mind: I won't hatch one for someone it'll eat.": ["まだら模様のドレイクの卵？ひとつと炭代に{n}フレン持ってきて。30分温めておくわ。孵るときはここにいて：最初に見た者が母親になるの。それと獣使い{n2}は必要よ。食べられちゃう人のために孵すつもりはないから。", "얼룩무늬 드레이크 알? 알 하나와 숯값 {n} 프렌을 가져와. 30분 동안 따뜻하게 해 줄게. 깰 때 여기 있어: 처음 본 존재가 어미야. 그리고 조련술 {n2}은 돼야 해. 잡아먹힐 사람을 위해 부화시키진 않아.", "斑点幼龙蛋？带一枚来，再加 {n} 友币炭钱，我替你保温半小时。破壳时你要在场：它第一眼看见谁，谁就是它的母亲。还有，得有驯兽 {n2}：我可不替会被它吃掉的人孵蛋。", "斑點幼龍蛋？帶一枚來，再加 {n} 友幣炭錢，我替你保溫半小時。破殼時你要在場：牠第一眼看見誰，誰就是牠的母親。還有，得有馴獸 {n2}：我可不替會被牠吃掉的人孵蛋。", "Trứng rồng đốm à? Mang cho ta một quả và {n} Fren tiền than, ta sẽ ủ ấm nửa giờ. Có mặt khi nó nở: nó thấy ai trước thì người đó là mẹ. Nhớ là Thuần thú {n2}: ta không ấp trứng cho kẻ sẽ bị nó ăn thịt.", "Telur drake berbintik? Bawakan satu dan {n} Fren untuk arangnya, akan kuhangatkan setengah jam. Ada di sini saat menetas: siapa yang pertama dilihatnya, itulah induknya. Ingat, Penjinakan {n2}: aku tak akan menetaskan untuk orang yang akan dimakannya.", "ไข่เดรกลายจุดเหรอ? เอามาใบหนึ่งกับค่าถ่าน {n} เฟรน แล้วข้าจะกกไว้ครึ่งชั่วโมง อยู่ตรงนี้ตอนมันฟัก: มันเห็นใครก่อน คนนั้นคือแม่ แล้วต้องมีการเลี้ยงสัตว์ {n2} ด้วยนะ ข้าไม่ฟักให้คนที่มันจะกินหรอก", "Benekli bir ejderha yumurtası mı? Bir tane ve kömür için {n} Fren getir, yarım saat sıcak tutarım. Çatladığında burada ol: ilk kimi görürse annesi odur. Ha, Hayvan bakıcılığı {n2} de lazım: yiyeceği birine yumurta çıkarmam.", "¿Un huevo de draco moteado? Tráeme uno y {n} Frens para el carbón, y lo mantendré caliente media hora. Estate aquí cuando eclosione: lo primero que vea será su madre. Y Doma de bestias {n2}, ojo: no voy a empollar uno para alguien a quien se va a comer.", "Um ovo de draco pintado? Traga um e {n} Frens para o carvão, e eu o mantenho quente por meia hora. Esteja aqui quando chocar: o primeiro que ele vir é a mãe. E Doma de feras {n2}, veja bem: não choco um para alguém que ele vai comer.", "Пятнистое яйцо дрейка? Принесите одно и {n} френов на уголь, и я полчаса подержу его в тепле. Будьте здесь, когда оно треснет: кого он увидит первым, тот ему и мать. И Звероводство {n2}, учтите: я не стану выводить дрейка для того, кого он съест.", "Плямисте яйце дрейка? Принесіть одне й {n} френів на вугілля, і я пів години потримаю його в теплі. Будьте тут, коли воно трісне: кого він побачить першим, той йому й мати. І Звірівництво {n2}, зважте: я не виводитиму дрейка для того, кого він з'їсть."],
  "You keep {n} of the {n2} you can. Which?": ["連れていられるのは{n2}匹中、今{n}匹。どれ？", "데리고 있을 수 있는 {n2}마리 중 {n}마리다. 어느 쪽?", "你能养 {n2} 个，现在养着 {n} 个。哪一个？", "你能養 {n2} 個，現在養著 {n} 個。哪一個？", "Ngươi đang giữ {n} trên {n2} con có thể giữ. Con nào?", "Kau memelihara {n} dari {n2} yang bisa kau pelihara. Yang mana?", "เจ้าเลี้ยงอยู่ {n} จาก {n2} ตัวที่เลี้ยงได้ ตัวไหน?", "Bakabileceğin {n2} hayvandan {n} tanesi sende. Hangisi?", "Tienes {n} de los {n2} que puedes tener. ¿Cuál?", "Você tem {n} dos {n2} que pode ter. Qual?", "У вас {n} из {n2}, что можно держать. Который?", "У вас {n} з {n2}, яких можна тримати. Котрий?"],
  "{n} of {n2} brought down by your companion.": ["相棒が倒したのは{n}／{n2}匹。", "동료가 쓰러뜨린 수: {n}/{n2}.", "你的伙伴已撂倒 {n}/{n2} 只。", "你的夥伴已撂倒 {n}/{n2} 隻。", "Bạn đồng hành đã hạ {n} trên {n2}.", "{n} dari {n2} dirobohkan pendampingmu.", "คู่หูของเจ้าล้มได้ {n} จาก {n2} ตัว", "Yoldaşın {n}/{n2} yaratık devirdi.", "{n} de {n2} abatidas por tu compañero.", "{n} de {n2} derrubadas pelo seu companheiro.", "Спутник свалил {n} из {n2}.", "Супутник звалив {n} з {n2}."],
  "A beastkeeper sets a companion its training for {n} Frens, and you do it together: {n2} deeds (fights won beside you, what it brings in, brushing it down, time on the road). Each tier makes it stronger, quicker to bring things in, deeper in the panniers and easier on the road.": ["獣使いが{n}フレンで相棒の訓練を課し、あなたが一緒にこなす：{n2}回の務め（共に勝つ戦い、持ってくる収穫、ブラッシング、旅の時間）。段階が上がるたびに強くなり、収穫が早まり、荷かごが深くなり、旅が楽になる。", "조련사가 {n} 프렌에 동료의 훈련을 정해 주고, 너는 함께 해낸다: {n2}번의 일 (곁에서 이긴 싸움, 가져오는 것, 빗질, 길 위의 시간). 단계마다 더 강해지고, 더 빨리 가져오고, 짐바구니가 깊어지고, 길이 편해진다.", "驯兽人收 {n} 友币为伙伴布置训练，由你和它一起完成：{n2} 件事（并肩打赢的仗、它带回的东西、给它刷毛、在路上的时光）。每升一阶它就更强、带回东西更快、驮篮更深、赶路更轻松。", "馴獸人收 {n} 友幣為夥伴佈置訓練，由你和牠一起完成：{n2} 件事（並肩打贏的仗、牠帶回的東西、給牠刷毛、在路上的時光）。每升一階牠就更強、帶回東西更快、馱籃更深、趕路更輕鬆。", "Người nuôi thú đặt bài huấn luyện cho bạn đồng hành với giá {n} Fren, và ngươi cùng nó làm: {n2} việc (thắng trận bên ngươi, thứ nó mang về, chải lông, thời gian trên đường). Mỗi bậc khiến nó mạnh hơn, mang đồ về nhanh hơn, giỏ thồ sâu hơn và đường đi nhẹ nhàng hơn.", "Penjinak menetapkan pelatihan pendamping seharga {n} Fren, dan kalian menjalaninya bersama: {n2} perbuatan (pertarungan dimenangkan di sisimu, hasil yang dibawanya, menyikatnya, waktu di jalan). Tiap tingkat membuatnya lebih kuat, lebih cepat membawa hasil, keranjang lebih dalam, dan jalan lebih ringan.", "ผู้เลี้ยงสัตว์ตั้งการฝึกให้คู่หูในราคา {n} เฟรน แล้วเจ้าทำด้วยกัน: {n2} ภารกิจ (ชนะการต่อสู้ข้างเจ้า ของที่มันนำมา แปรงขน เวลาบนเส้นทาง) แต่ละขั้นทำให้มันแข็งแกร่งขึ้น นำของมาเร็วขึ้น ตะกร้าบรรทุกลึกขึ้น และเดินทางง่ายขึ้น", "Bir bakıcı {n} Fren karşılığında yoldaşına eğitim belirler, siz birlikte yaparsınız: {n2} iş (yanında kazanılan dövüşler, getirdikleri, tımar, yolda geçen zaman). Her kademe onu daha güçlü, daha çabuk getiren, heybesi daha derin ve yolda daha rahat yapar.", "Un cuidador de bestias le pone a tu compañero su adiestramiento por {n} Frens, y lo hacéis juntos: {n2} hazañas (combates ganados a tu lado, lo que trae, cepillarlo, tiempo en el camino). Cada grado lo hace más fuerte, más rápido en traer cosas, de alforjas más hondas y más llevadero en el camino.", "Um tratador passa o treinamento do seu companheiro por {n} Frens, e vocês fazem juntos: {n2} feitos (lutas vencidas ao seu lado, o que ele traz, escová-lo, tempo na estrada). Cada nível o deixa mais forte, mais rápido para trazer coisas, com alforjes mais fundos e mais leve na estrada.", "Зверовод за {n} френов задаёт спутнику обучение, а проходите его вы вместе: {n2} дел (бои, выигранные бок о бок, то, что он приносит, чистка, время в дороге). Каждая ступень делает его сильнее, быстрее в добыче, с более глубокими вьюками и легче в пути.", "Звірівник за {n} френів задає супутникові навчання, а проходите його ви разом: {n2} справ (бої, виграні пліч-о-пліч, те, що він приносить, чищення, час у дорозі). Кожен щабель робить його сильнішим, швидшим у здобутку, з глибшими в'юками й легшим у дорозі."],
};
